INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (173, 'tm222549', 'The Driftin'' Kid', 2, 'In this western, the good-guy battles his bad-guy double and his band of outlaws to protect a purty gal''s ranch.', 1941, NULL, 57, NULL, 'tt0033559', 6.0, 33.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (174, 'tm101627', 'The Return Of Chandu', 2, 'The cult of Ubasti, headquartered on the isle of Lemuria, believes that Princess Nadji of Egypt is a reincarnation of their long-dead goddess, Ossana, and intend to sacrifice her so that Ossana may be resurrected. Nadji has sought refuge at the California home of Frank Chandler, an American educated in the Ancient East and familiar with White Magic and thus calls himself "Chandu". Vindhyan, high priest of the cult''s California base has learned of this, however, and works his Black Magic to gain control of Nadji. Chandu is able to rescue her but she is in a deep trance which he cannot penetrate, so attempts to move her to safety in the South Seas, unaware that the cult has a base there also and that Vindhyan has stowed aboard his chartered yacht.  One of two feature films edited from the same-title, same-year movie serial, this one is comprised of the first four chapters simply edited together.', 1934, NULL, 60, NULL, 'tt0025713', 5.9, 359.0, 0.6, NULL);
