INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (188, 'tm1521', '''Neath the Arizona Skies', 2, 'Chris Morrell, the guardian of half-Indian girl Nina, is helping her find her missing white father. so she can cash in on her late mother''s oil lease. Outlaw Sam Black is after the girl and her father as well. Besides dealing with the Black gang, Morrell has to find another robber, Jim Moore, who switches clothes with him after he finds Chris unconscious from a fight with Sam Black. Along the way, he meets a lady who''s the sister of Jim Moore, another bad hombre who''s in cahoots with Jim Moore, and an old friend who takes in Nina and helps Chris locate Nina''s father and fight off the various desperadoes', 1934, NULL, 52, NULL, 'tt0024805', 5.1, 997.0, 3.69, 4.6);
