INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (252, 'tm1345', 'Abilene Town', 2, 'Marshall Dan Mitchell, who is the law in Abilene, has the job of keeping peace between two groups. For a long time, the town had been divided, with the cattlemen and cowboys having one end of town to themselves, while townspeople occupied the other end. Mitchell liked it this way, it made things easier for him, and kept problems from arising between the two factions. However…', 1946, NULL, 89, NULL, 'tt0038284', 6.2, 1000.0, 2.833, 5.3);
