INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (301, 'tm83723', 'Mr. Bug Goes to Town', 2, 'The happy tranquility of Buggsville is shattered when the populace learns that a colossal skyscraper is to be built over their tiny town.', 1941, 3, 78, NULL, 'tt0033727', 6.9, 1261.0, 2.318, 6.1);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (302, 'tm116860', 'One Rainy Afternoon', 2, 'Suave French actor Philippe Martin provokes a scandal when, in a darkened theater, he mistakes young Monique for his mistress, Yvonne, and tries to kiss her. Charged with assault, the quick-thinking Philippe claims it''s French tradition to do as he did, and is let go. To his surprise, Philippe learns that Monique has paid his fine. As the tabloids exploit the situation, Monique dates Philippe, until a photo appears of him kissing Yvonne.', 1936, NULL, 80, NULL, 'tt0028062', 5.9, 276.0, 2.069, 4.4);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (303, 'tm87782', 'Wide Open Town', 2, 'Belle Langtry runs a town being taken over by cattle rustlers. She is also a front for the outlaws, who are led by Steve Fraser. Hoppy gets elected sheriff and cleans up the town with help from the Bar 20 boys.', 1941, NULL, 79, NULL, 'tt0034391', 6.6, 215.0, 1.023, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (304, 'tm23348', 'Joan the Woman', 2, 'A WWI English officer is inspired the night before a dangerous mission by a vision of Joan of Arc, whose story he relives.', 1916, NULL, 138, NULL, 'tt0177807', 6.4, 585.0, 3.011, 5.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (305, 'tm84796', 'My Pal Trigger', 2, 'Gabby doesn´t want to breed his horse the Golden Sovereign with Roy''s. When Sovereign and Roy''s horse escape, the Sovereign get shoot accidentally by Skoville but Roy is blamed and jailed. A year later Roy returns with Trigger, the son of the Sovereign. When Skoville reveals he was present when the horse was shot, Roy sees an opportunity to clear his name.', 1946, NULL, 79, NULL, 'tt0038764', 6.4, 505.0, 3.636, 6.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (306, 'tm54261', 'Indiscreet', 2, 'A young woman jeopardizes the relationship with the man she loves when a no-account from her past shows up.', 1931, NULL, 92, NULL, 'tt0022000', 6.2, 1447.0, 1.062, 5.8);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (307, 'tm80661', 'The Son of Monte Cristo', 2, 'Rightful owner of the kingdom, the Duchess of Zona, is engaged in a power struggle with the evil General Gurko. Edmond, the son of Monte Cristo, dons many disguises to come to the aid of the Duchess.', 1940, NULL, 102, NULL, 'tt0033076', 6.2, 791.0, 5.124, 6.0);
