INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (437, 'tm99682', 'The Man From Utah', 2, 'The Marshal sends John Weston to a rodeo to see if he can find out who is killing the rodeo riders who are about to win the prize money. Barton has organized the rodeo and plans to leave with all the prize money put up by the townspeople. When it appears that Weston will beat Barton''s rider, he has his men prepare the same fate for him that befell the other riders.', 1934, 3, 55, NULL, 'tt0025455', 5.1, 1138.0, 2.972, 4.9);
