INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (448, 'tm6772', 'Who Killed Doc Robbin?', 2, 'A group of people find themselves trapped in a creepy mansion, complete with secret passageways, a mad doctor and a murderous gorilla.', 1948, NULL, 55, NULL, 'tt0040966', 4.6, 291.0, 1.395, 3.8);
