INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (484, 'tm4564', 'Dangerous Passage', 2, 'Joe Beck leaves Central America so that he can return to Texas and collect a large inheritance, but he picks a dangerous ship on which to travel.', 1944, NULL, 60, NULL, 'tt0036741', 5.4, 307.0, 0.84, 4.9);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (485, 'tm112173', 'The President''s Mystery', 2, 'The screenplay for this mystery is based upon a story suggested to Liberty Magazine by President Franklin D. Roosevelt. It is the tale of a prominent lawyer who shocks his snooty friends, family and colleagues by abruptly abandoning his successful practice and his wife to find true happiness. He soon falls in love with another woman and continues to keep a low profile until he learns that his first wife stands accused of murdering him', 1936, NULL, 80, NULL, 'tt0028135', 5.6, 185.0, 1.39, 5.2);
