INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (488, 'tm220934', 'Riddle Ranch', 2, 'Rigging a horse race, Don Carlos wins a lot of money. When he loses his winnings at the gambling table, he shoots the dealer with Horton''s gun. Horton is arrested but cannot prove his innocence.', 1935, NULL, 63, NULL, 'tt0137193', 4.3, 24.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (489, 'tm82785', 'In Old Cheyenne', 2, 'Roy is a newspaper reporter. He goes to Cheyenne to cover the activities of supposed bad guy Arapahoe Brown. Roy, of course, discovers who the real bad guy is.', 1941, NULL, 58, NULL, 'tt0033752', 6.2, 127.0, 2.089, 3.5);
