INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (491, 'tm67650', 'The Shadow Strikes', 2, 'Lamont Cranston assumes his secret identity as "The Shadow", to break up an attempted robbery at an attorney''s office. When the police search the scene, Cranston must assume the identity of the attorney. Before he can leave, a phone call summons the attorney to the home of Delthern, a wealthy client, who wants a new will drawn up. As Cranston meets with him, Delthern is suddenly shot, and Cranston is quickly caught up in a new mystery.', 1937, NULL, 62, NULL, 'tt0029542', 4.8, 493.0, 1.522, 4.7);
