INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (496, 'tm89670', 'That Brennan Girl', 2, 'Raised by Natalie Brennan, a flamboyant and irresponsible mother, Ziggy Brennan gets involved in hustling men at a young age. She hangs around with a wild crowd and learns gets her "street smarts" first from her mother, who wants everyone to think they are sisters, and then from Denny Reagan, an older man. He starts teaching her his tricks of the trade and she falls right in line with his crooked ways. Then one night she meets Martin J. ''Mart'' Neilson, a tall, handsome, honest farmer boy who''s a sailor and they fall in love. While he''s away fighting the war, she discovers she''s pregnant.', 1946, NULL, 95, NULL, 'tt0039020', 6.5, 306.0, 0.864, 5.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (497, 'tm160235', 'The Mystery of Mr. Wong', 2, 'Detective James Lee Wong must find the "Eye of the Daughter of the Moon," a priceless but cursed sapphire stolen in China and smuggled to America. His search takes him into the heart of Chinatown and to the dreaded "House of Hate" to find the deadly gem before it can kill again.', 1939, NULL, 68, NULL, 'tt0031704', 6.1, 841.0, 1.946, 6.1);
