INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (515, 'tm73642', 'Klondike Fury', 2, 'In this Alaskan adventure, a surgeon becomes a pilot after he messes up an operation. Unfortunately, he crashes during a storm and finds himself cared for by a lovely woman. He gets a chance to reclaim his self-esteem when her son suddenly needs the same operation the surgeon botched.', 1942, NULL, 68, NULL, 'tt0034948', 4.1, 83.0, 1.4, 3.7);
