INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (561, 'tm8013', 'Barefoot Boy', 2, 'A spoiled boy sent to the country to grow-up. He has to deal with life, friends and crooks.', 1938, NULL, 63, NULL, 'tt0029898', 5.6, 88.0, 1.18, 5.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (562, 'tm68754', 'Kermit Maynard Collection (Whistling Bullets', 2, 'Ace Beldon is in prison, but with his stolen bonds not recovered, Capt. Saunders has an idea. He sends Graham to prison and has him and Beldon break out. With Ranger Raymond assisting, they make their escape and get to the hangout run by Stone. But the plan starts to go awry when Sam overhears Graham talking with the Captain and reports back to Stone.', 1937, NULL, 57, NULL, 'tt0029768', 5.6, 50.0, 1.045, 6.0);
