INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (584, 'tm65315', 'Come on, Cowboys', 2, 'Harris and Rigby own a circus. Rigby is a counterfeiter and frames his partner. The Mesquiteers learn Rigby is the culprit and get a confession from one of his men only to lose the case when the man is murdered in jail. The Mesquiteers try again and send Lullaby to try and win some of the fake bills in a card game.', 1937, NULL, 58, NULL, 'tt0028732', 6.1, 79.0, 0.708, 6.0);
