INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (587, 'tm99611', 'Palooka', 2, 'Joe Palooka is a naive young man whose father Pete was a champion boxer, but his lifestyle caused Joe''s mother Mayme to leave him and to take young Joe to the country to raise him.', 1934, NULL, 86, NULL, 'tt0025619', 6.0, 370.0, 2.558, 1.8);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (588, 'tm800556', 'Crashin'' Broadway', 2, 'When Tad Wallace''s act flops on Broadway, he joins a troop heading west. In a small town they run into Jeffries who has just burned down the theater. When Jeffries kills Griswold, Tad has a plan to trap him by using the talents', 1932, NULL, 59, NULL, 'tt0023914', 4.0, 24.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (589, 'tm806832', 'Fighting Fury', 2, 'A Spanish-American boy raised by his Mexican servant, Clay Hill, Jr. vows vengeance on the three ranchers who murdered his parents.', 1924, NULL, 61, NULL, 'tt0014893', 6.2, 14.0, 1.4, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (590, 'tm144977', 'Cobra', 2, 'Rodrigo, an impoverished Italian nobleman (Rudolph Valentino) takes a job with a New York antique dealer he met overseas. Swearing off women, Rodrigo focuses on his job. But complications arise when he falls in love with his friend''s secretary-- and his friend''s wife looks to make a date with him.', 1925, 5, 76, NULL, 'tt0015693', 6.4, 747.0, 0.954, 6.4);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (591, 'tm67012', 'Bill Cracks Down', 2, 'William Reardon, a steel magnate, dies and leaves a strange will. When his spineless and dandified heir and son returns home from living in Paris, he finds "Tons'' Walker, a strong and burly steel worker running the company, per his late-father''s will request. He also finds that his father''s will specifies the Junior will change his name to Bill Hall and work in the family steel mill for a year under the fake name. Walker''s job is to make a man out of the son. The son is not overjoyed by this prospect. Neither is Walker.', 1937, NULL, 61, NULL, 'tt0028634', 5.6, 90.0, 0.6, 6.0);
