INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (607, 'tm221846', 'Colorado Kid', 2, 'When Hines kills the Colonel for his money, the Colorado Kid is arrested and then found guilt of the murder. Bibben beaks him out of jail and later identifies some of the bills spent by Hines to have been part of the money stolen from the Colonel. The Kid now knows he is the one he is after and heads out to get a confession.', 1937, NULL, 56, NULL, 'tt0028728', 6.0, 51.0, 0.6, NULL);
