INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (610, 'tm139223', 'Jaws of Justice', 2, 'Seeker Dean has found the gold he has been looking for for 15 years. Heading for the Government office, Boone Jackson kills him. Kickabout finds a cryptogram as to the gold''s location and Sergeant Kinkaid solves the puzzle. But Jackson learns of the gold''s location and to get it, he sets out to dynamite the dam that would flood the entire communuty.', 1933, NULL, 58, NULL, 'tt0024192', 4.0, 55.0, 0.996, 4.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (611, 'tm264751', 'Spotlight Scandals', 2, 'A down-on-his luck actor teams up with a singing barber to do a vaudeville act. Its success eventually leads them to Broadway, but things start to go awry.', 1943, NULL, 71, NULL, 'tt0036382', 5.5, 33.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (612, 'tm209470', 'Rainbow Ranch', 2, 'An emergency at his Aunt''s ranch gets Ed Randall leave from the Navy. He returns to find the water cut off and her note due the next day. When the man he seeks legal advice from is murdered, Ed is accused and he now finds himself in jail with a lynch mob forming outside.', 1933, NULL, 55, NULL, 'tt0132461', 4.8, 30.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (613, 'tm82509', 'Jesse James at Bay', 2, 'When Jesse learns that Krager is cheating settlers, he and his gang rob trains to obtain money for them to purchase their land. Krager, finding a Jesse look alike in Burns, hires him to wreck havoc on the ranchers. When Jesse kills Burns he switches clothes and goes after the culprits.', 1941, NULL, 56, NULL, 'tt0033771', 5.8, 172.0, 1.312, 5.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (614, 'tm54027', 'The Lady Refuses', 2, 'A wealthy London nobleman hires a pretty but poor young girl to distract his playboy son from marrying a golddigger. Complications ensue when the girl and the father begin to fall for each other, and things get even more complicated when the son declares his love for her, too.', 1931, NULL, 72, NULL, 'tt0022046', 6.0, 346.0, 1.905, 5.3);
