INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (617, 'tm88481', 'Big Town After Dark', 2, 'A crusading newspaper reporter battles big-city gambling interests.', 1947, NULL, 69, NULL, 'tt0039187', 5.5, 213.0, 1.687, 5.6);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (618, 'tm800789', 'Badge of Honor', 2, 'Hoping to impress a pretty girl he''s after, a playboy poses as a newspaperman and goes after a big story.', 1934, 2, 68, NULL, 'tt0024858', 6.0, 38.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (619, 'tm63278', 'Manhattan Merry-Go-Round', 2, 'In this musical comedy, a crooked record producer uses his mob connections to force performers to do their stuff. The trouble really begins when the gangster''s strong-arm tactics nearly cause a singer to lose his fiancée. A wide variety of entertainers appear including cowboy crooner Gene Autry, baseball hero Joe DiMaggio, and big band stars Cab Calloway, Ted Lewis, and the Kay Thompson Singers. Songs include "Mamma I Wanna Make Rhythm," "Manhattan Merry-Go-Round," "Heaven?," "I Owe You," and "It''s Round-up Time in Reno."', 1937, NULL, 89, NULL, 'tt0029209', 5.7, 146.0, 1.286, 5.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (620, 'tm5043', 'Parole, Inc.', 2, 'A federal agent''s life is in danger when he''s exposed while investigating a parole scheme.', 1948, NULL, 71, NULL, 'tt0041733', 5.7, 368.0, 2.068, 4.6);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (621, 'tm119299', 'Cattle Stampede', 2, 'Billy the Kid and Fuzzy Jones are on their way out of Arizona being chased by some riders who hope to cash in on the reward money for their capture. They are warned in time by Ed Dawson, but Ed is wounded in the getaway. They get a doctor to attend to Ed. The latter tells them there is a range war in progress across the border and that he is looking for men to help make a cattle drive to the rail junction.', 1943, NULL, 57, NULL, 'tt0035723', 6.2, 91.0, 0.967, 5.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (622, 'tm84443', 'Hold That Woman!', 2, 'A skip tracer--someone who collects late payments from people who''ve purchased appliances, etc., or takes them back them when they don''t pay--repossesses a small radio from a deadbeat who''s skipped payments. What he doesn''t know is that a gang that has stolen diamonds from a Hollywood movie star has stashed them inside the radio, and they start hunting for him.', 1940, NULL, 67, NULL, 'tt0032602', 5.6, 156.0, 2.074, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (623, 'tm145525', 'Diamond Trail', 2, 'Reporter Speed Morgan helps Flash Barrett escape from the police and this gets him into Flash''s gang where he poses as a gangster. Flash and his gang head west guning for Bill Miller who failed to send some diamonds on to Flash. Speed hopes to bring Flash to justice but is in trouble when his true identity is revealed.', 1932, NULL, 58, NULL, 'tt0022819', 5.6, 54.0, 0.68, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (624, 'tm67989', 'Born to the West', 2, 'Dare Rudd takes a shine to his cattleman cousin Tom''s girlfriend who asks Tom to hire Dare to head the big cattle drive. Dare loses the money for the drive to cardsharps, but Tom wins it back, but Dare must save Tom''s life.', 1937, NULL, 59, NULL, 'tt0169997', 5.7, 910.0, 3.02, 4.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (625, 'tm217952', 'Trail to San Antone', 2, 'Gene Autry is back near the saddle, trying to help out a crippled jockey. Gene is certain that the jockey can ride in the Big Race if the lad can regain his self-confidence. Meanwhile, Gene and comical sidekick Sterling Holloway have another problem on their hands: A rogue stallion has "kidnapped" Gene''s prize mare. Piloting a plane, Autry seeks out and locates the stallion.', 1947, NULL, 54, NULL, 'tt0039909', 6.3, 86.0, 0.71, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (626, 'tm69878', 'Dreaming Out Loud', 2, 'Lum and Abner work at a general store in Arkansas. There they get involved in some misadventures with the locals.', 1940, 2, 81, NULL, 'tt0032417', 6.4, 114.0, 1.053, 5.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (627, 'tm5082', 'Law of the North', 2, 'Hanley shoots a man and then frames Bill Roberts. Being the Judge he then holds court planning to hang Bill but Bill''s friends effect his escape. Andy tries to lead Hanley astray by misleading him as to Bill''s location. But Bill changes plans and Hanley catches up with him and this leads to the showdown.', 1932, NULL, 55, NULL, 'tt0023122', 4.7, 36.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (628, 'tm82254', 'Beware', 2, 'Ware College is a small Black college in Ware, Ohio. Once prominent, it is now low in attendance, low in enrollment and low on money; and at a meeting with instructors Drury and Annabelle Brown, Dean Hargreaves reveals that CEO Benjamin Ware III, grandson of the college''s founder, claims the estate of his late grandfather is now also destitute, which they believe is untrue and a result of Annabelle''s having spurned his affections. They decide to appeal to their famous alumni for financial help thru a reunion, and invitations are sent. Many could help; but surely not Lucius Jordan, a timid lad who loved Annabelle too but dropped out under pressure from Ware. What they don''t know is, he''s now Louis Jordan, king of swing and leader of the Tympani Band.', 1946, NULL, 54, NULL, 'tt0038353', 5.9, 84.0, 1.151, 5.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (629, 'tm5364', 'Sinners in Paradise', 2, 'The survivors from a plane crash are washed up on an island where the only inhabitants are Mr. Taylor and his servant, Ping. The mismatched group must learn to get along and work together if they are to convince Taylor to let them borrow his boat and return to the main land.', 1938, NULL, 65, NULL, 'tt0030754', 5.7, 457.0, 0.6, 6.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (630, 'tm4308', 'Mason of the Mounted', 2, 'Canadian Mountie Mason is sent south of the border to look for a horse thief with only a watch chain for evidence. He befriends young Andy and when Calhoun hits Andy, Mason and Calhoun fight. In the scuffle Calhoun''s watch with the missing chain is dislodged. Mason then sets out to bring in Calhoun and his gang.', 1932, NULL, 58, NULL, 'tt0023195', 5.2, 69.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (631, 'tm85443', 'Pirates on Horseback', 2, 'Hoppy, Lucky and California search for a mine owned by Trudy Pendleton after it was taken from her by thw swindling gambler Ace Gibson. They find the mine and Hoppy fights Gibson over it.', 1941, NULL, 69, NULL, 'tt0034030', 6.3, 166.0, 1.198, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (632, 'tm68340', 'Secret Valley', 2, 'Rancher entertains girl in Nevada to get a divorce. Then her gangster husband shows up.', 1937, NULL, 60, NULL, 'tt0029532', 6.1, 45.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (633, 'tm89643', 'Wrangler''s Roost', 2, 'The notorious outlaw Black Bart has reappeared and the Range Busters are sent to investigate. When they find that Black Bart is now a respectable citizen and that someone is impersonating him, they set a trap for the robber.', 1941, NULL, 57, NULL, 'tt0034403', 5.9, 44.0, 1.628, 6.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (634, 'tm5995', 'The Racketeer', 2, 'This late-20s gangster movie features Carole Lombard as a young gal who agrees to marry a smooth-talking gangster in exchange for the mob man''s pledge to arrange a big-time concert appearance for her violinist boyfriend. The only thing that can save the day for the mis-aligned lovers is a shootout between the cops and the gangland thugs. This film is notable because it is one of the early ''talkies," and uses the newly developing audio technology with abandon. In fact, most of the action takes place off screen and the characters tell the cameras just what''s happened. This one''s small on sets, big on dialog.', 1929, 3, 66, NULL, 'tt0020305', 5.4, 412.0, 1.957, 4.2);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (635, 'tm70213', 'Wildcat', 2, 'Wildcatter Johnny Maverick and his pal go to a town in oil country offering $25,000 to the person who brings in the first well. They find oil on the outskirts but have to sell a share to a promoter who hires Johnny''s old enemy.', 1942, NULL, 70, NULL, 'tt0035562', 5.6, 116.0, 1.756, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (636, 'tm3623', 'Lights of Old Santa Fe', 2, 'Sandwiched in between the numerous musical numbers, the Gabby Whittaker and Madden rodeo''s are competing for bookings. When Gabby gets a date in Albuquerque, Madden has his man destroy his equipment. Roy finds a broken rawhide rope at the scene and uses it to bring Madden to justice.', 1944, 3, 78, NULL, 'tt0037018', 6.0, 209.0, 1.734, 5.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (637, 'tm59962', 'Rim of the Canyon', 2, '20 years ago, 3 men robbed a stage and hid $30,000. They were caught and sent to prison by Marshal Steve Autry. 20 years later, the men bust out of prison and return to the ghost town where they stashed their treasure searching. Steve''s grandson picks up where Steve left off to foil the plans of the outlaws.', 1949, NULL, 70, NULL, 'tt0041810', 6.2, 152.0, 1.019, 5.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (638, 'tm6281', 'Shine On Harvest Moon', 2, 'A rustler''s son (Roy Rogers) courts a rancher''s daughter (Mary Hart) during a range war.', 1938, NULL, 54, NULL, 'tt0030742', 6.5, 102.0, 1.455, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (639, 'tm207959', 'Devil''s Playground', 2, 'A remake of Frank Capra''s Submarine (1928), Devil''s Playground is a snappy Columbia "B plus" picture starring Richard Dix and Chester Morris. Submarine officers Dorgan (Dix) and Mason (Morris) battle on land for the affections of dance-hall girl Carmen (Dolores del Rio). She marries Dorgan but makes a play for Mason when her husband is on duty. The romantic rivalry is forgotten when Dorgan must rescue Mason and his crew from a sunken sub.', 1937, NULL, 74, NULL, 'tt0028783', 6.1, 153.0, 1.76, 6.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (640, 'tm8320', 'Crashing Through Danger', 2, 'Three electrical linemen work through the hazardous conditions of the Depression Era. Sparks fly, and things become truly dangerous, when Ann (Sally Blane) comes between this band of brothers. Things get worse, after they move in together, following the death of her father, their supervisor, "Pop" Foster (Robert Homans), from an industrial accident.', 1938, NULL, 61, NULL, 'tt0030023', 4.9, 70.0, 1.711, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (641, 'tm1733', 'Adventure in Iraq', 2, 'Five Allied soldiers in an airplane flying to Egypt crash-land in Iraq. They are taken in by a local sheik, but soon begin to suspect that he may not be quite as friendly as he appears to be.', 1943, NULL, 65, NULL, 'tt0035610', 5.0, 172.0, 0.95, 6.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (642, 'tm15309', 'The Phantom of 42nd Street', 2, 'A theatre critic (Dave O''Brien) teams up with a cop (Jack Mulhall) to investigate the murder of a Broadway actor.', 1945, NULL, 58, NULL, 'tt0037985', 5.2, 325.0, 1.985, 3.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (643, 'tm63754', 'Wallaby Jim of the Islands', 2, 'Wallaby Jim and his men have just found a valuable source of pearls in the South Pacific. But Jim''s associate Norman has put the whole operation in jeopardy because of his gambling problem. Jim''s unscrupulous rival Richter decides to exploit the situation by jumping Jim''s claim and trying to take over for himself.', 1937, NULL, 61, NULL, 'tt0029745', 5.1, 72.0, 0.655, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (644, 'tm19501', 'No Man''s Law', 2, 'A wild stallion (Rex the Wonder Horse) becomes the protector of a prospector and his foster daughter as two thugs plot to steal their claim.', 1927, NULL, 54, NULL, 'tt0334008', 6.6, 80.0, 0.657, 6.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (645, 'tm111597', 'Death Valley Rangers', 2, 'When a fed-up businessman tires of watching gold shipments disappear without a trace, he calls in the Trail Blazers (Ken Maynard, Hoot Gibson and Bob Steele) -- a legendary trio of law enforcers -- to find the gold and figure out who''s behind the thefts.', 1943, NULL, 59, NULL, 'tt0035788', 5.7, 148.0, 1.4, 7.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (646, 'tm67963', 'Boots and Saddles', 2, 'Young Englishman inherits ranch which he wants to sell, but Gene''s gonna turn him into a real westerner instead. When new owner Spud arrives from England, Autry convinces him not to sell the ranch but to raise horses for the Army. When both Autry''s and Neale''s bids are the same, the Colonel calls for a race to decide the winner. But that night Neale has Autry''s stable burned.', 1937, NULL, 58, NULL, 'tt0028646', 5.7, 244.0, 1.906, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (647, 'tm131498', 'Ella Cinders', 2, 'Poor Ella Cinders is much abused by her evil step-mother and step-sisters. When she wins a local beauty contest she jumps at the chance to get out of her dead-end life and go to Hollywood, where she is promised a job in the movies. When she arrives in Hollywood, she discovers that the contest was a scam and the job non-existent. But through pluck, luck, and talent, she makes it in the movies anyway, and finds true love.', 1926, NULL, 75, NULL, 'tt0016822', 7.0, 1015.0, 1.607, 7.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (648, 'tm111881', 'Fast Bullets', 2, 'Two Texas Rangers (Tom Tyler, Rex Lease) nab smugglers and rescue a woman (Margaret Nearing) from a runaway wagon.', 1936, NULL, 58, NULL, 'tt0027610', 5.5, 114.0, 0.988, 4.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (649, 'tm60500', 'The Cowboy and the Indians', 2, 'Finding Indians stealing from his ranch, Gene learns they are suffering from malnutrition. Store owner Martin is cheating them and now he is after the Chief''s valuable necklace. When the dying chief is found, having been attacked and robbed, Martin blames Lakhona who would become the new chief. When Gene helps Lakhona they soon find themselves fleeing from the law.', 1949, NULL, 68, NULL, 'tt0041264', 6.5, 157.0, 1.327, 7.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (650, 'tm783343', 'Tracy the Outlaw', 2, 'A fictionalized biography of famed Western outlaw Harry Tracy.', 1928, NULL, 69, NULL, 'tt0171839', 4.7, 19.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (651, 'tm110713', 'Racing Blood', 2, 'Frankie Reynolds (Frankie Darro'' ), youngest member of a family of jockeys, borrows $4.85 (yes, four dollars and eighty-five cents) from his sister Phyllis (Gladys Blake), who is not a jockey, to buy a crippled colt from the stables owned by Clay Harrison (Kane Richmond). He nurses the colt back to health, and in two years has one of the fastest horses in the country.', 1936, NULL, 61, NULL, 'tt0030648', 4.4, 38.0, 1.176, 4.0);
