INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (654, 'tm7249', 'Prison Break', 2, 'Barton MacLane stars as a tuna fisherman who has been wrongfully convicted of a murder he did not commit. His exemplary behavior in prison ensures that he is up for early parole. He realizes, however, that his movements will be limited, and he will be unable to join and wed his beloved. The only solution is to escape and hunt down the real killer, himself.', 1938, NULL, 72, NULL, 'tt0030625', 6.1, 278.0, 1.265, 4.6);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (655, 'tm72149', 'The Light of Western Stars', 2, 'A prim Eastern woman heads West and ends up in the arms of a vulgar, alcoholic ranch hand.', 1940, NULL, 64, NULL, 'tt0032706', 5.4, 162.0, 1.978, NULL);
