INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (690, 'tm856913', 'Ridin'' On', 2, 'Bolton has organized a feud between the Rork''s and the O''Neil''s. He has rustled cattle and killed a man putting the blame on Danny O''Neil. Tom Rork has found a bullet with markings on it that he hopes will clear Danny and bring in the real killer.', 1936, NULL, 56, NULL, NULL, NULL, NULL, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (691, 'tm116863', 'The Old Corral', 2, 'As the sheriff of a small western town, Autry sings his way into a relationship with Eleanor, a singer from a Chicago nightclub who earlier witnessed a murder.', 1936, NULL, 54, NULL, 'tt0028054', 5.8, 251.0, 1.255, 7.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (692, 'tm1925', 'The Affairs of Anatol', 2, 'Socialite Anatol Spencer, finding his relationship with his wife lackluster, goes in search of excitement. After bumping into old flame Emilie, he lets an apartment for her only to find that she cheats on him. He is subsequently robbed, conned, and booted from pillar to post. He decides to return to his wife and discovers her carousing with his best friend Max.', 1921, NULL, 117, NULL, 'tt0011909', 6.6, 1299.0, 1.716, 5.3);
