INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (695, 'tm4340', 'Career Girl', 2, 'Joan Terry, from Kansas City, comes to New York to get a job on the stage. But until she finds an opportunity, she stays at a boarding house where other talent is also waiting. To get a better chance, the people there decide to build a talent pool, where the person with the most chances for a job gets the full support, trying to get jobs for the others there too - and Joan is chosen to do that. But this is not so easy when her fiance is trying to keep her away from the stage...', 1944, NULL, 69, NULL, 'tt0035714', 5.5, 184.0, 0.664, 5.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (696, 'tm264793', 'Fugitive of the Plains', 2, 'Billy joins an outlaw band led by woman to clear his name of their crimes, which are being blamed on him.', 1943, NULL, 56, NULL, 'tt0040721', 5.2, 90.0, 0.739, 5.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (697, 'tm62442', 'Public Cowboy No. 1', 2, 'Deputies Gene Autry and Frog go up against modern cattle rustlers. These rustlers use technology such as, airplanes, radios and refrigerated trucks to steal the cows, butcher them in the field and ship them out before getting caught. This causes the town to bring in a modern NYC detective to catch the crooks, but will Autry and Frog be permanently out of a job?', 1937, 2, 54, NULL, 'tt0029445', 5.7, 156.0, 1.074, 5.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (698, 'tm77416', 'Romance on the Range', 2, 'Romance on the Range is a 1942 American film. Fur theives are looting the traps on the ranch where Roy is foreman and they have murdered one of Roy''s friends.', 1942, NULL, 63, NULL, 'tt0035266', 6.2, 112.0, 1.58, 6.5);
