INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (700, 'tm60311', 'Daughter of the West', 2, 'A convent-raised woman (Martha Vickers) learns of her American Indian heritage through romance with an educated Navajo (Philip Reed) during the 1880s.', 1949, NULL, 77, NULL, 'tt0041282', 6.0, 31.0, 0.916, NULL);
