INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (709, 'tm111550', 'Tornado', 2, 'The owner of an Illinois coal mine struggles to keep his business in operation, all the while unaware that among his employees is a saboteur planning destruction and chaos.', 1943, 2, 83, NULL, 'tt0036451', 6.1, 103.0, 3.197, 5.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (710, 'tm63972', 'The Great Dan Patch', 2, 'David Palmer, a young chemist, returns to his father''s Indiana farm, to marry a local school teacher, Ruth Treadwell. David meets again his father''s horse-trainer, Ben Lathrop, whose daughter, Cissy, has left high school to help her father. Palmer marries and becomes wealthy through an invention, and is able to indulge his socially-ambitious wife. His father dies and Palmer returns to Indiana, where his interest in harness-racing is rekindled, as is his interest in Cissy Lathrop.', 1949, NULL, 94, NULL, 'tt0041426', 5.9, 232.0, 3.105, 5.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (711, 'tm111459', 'Postal Inspector', 2, 'Postal inspectors track down money stolen from a railroad car.', 1936, NULL, 58, NULL, 'tt0028132', 5.2, 237.0, 0.739, 8.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (712, 'tm15017', 'The Missing Corpse', 2, 'A feud between rival newspapermen Kruger (Bromberg) and McDonald (Guilfoyle) goes deadly when blackmailing McDonald ends up murdered and his corpse planted in the trunk of Kruger''s car. Good guy Kruger attempts to hide McDonald''s body, with the help of chauffeur Hogan (Jenks), to keep from being charged with murder. However, zany scenarios occur as the body just won''t stay hidden, and keeps on popping up in multiple places where Kruger is located, leading to him hiding the body again and again while Kruger tries to find the real killer.', 1945, NULL, 62, NULL, 'tt0037918', 5.8, 226.0, 1.728, 7.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (713, 'tm114230', 'Ghost-Town Gold', 2, 'The three Mesquiteers try to recover the gold stolen by a gang in its effort to ruin the banker/mayor who ordered them to leave town.', 1936, NULL, 55, NULL, 'tt0027670', 6.1, 111.0, 0.669, 5.0);
