INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (716, 'tm210313', 'Guilty of Treason', 2, 'The story of Cardinal Josef Mindzhenty, a Roman Catholic cardinal from Hungary who spoke out against both the Nazi occupation of his country during World War II and the Communist regime that replaced it after the war.', 1950, NULL, 86, NULL, 'tt0041437', 5.9, 192.0, 1.081, 5.8);
