INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (718, 'tm52843', 'Clearing the Range', 2, 'A cowboy rides by night to catch the man who killed his brother.', 1931, NULL, 61, NULL, 'tt0021751', 5.3, 121.0, 0.934, 4.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (719, 'tm66674', 'Dynamite', 2, 'Two members of a dynamite crew--a rugged veteran and a young college drop-out--finds themselves at odds regarding safety precautions for their co-workers.', 1949, NULL, 68, NULL, 'tt0039343', 5.0, 24.0, 0.841, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (720, 'tm137955', 'Broken Dreams', 2, 'Medical intern Robert Morley is distraught after his wife dies in childbirth. He''s resentful of his new son and wants nothing to do with him. He leaves the child with his aunt and uncle and heads off to Europe to pursue his medical studies. Morley returns to his hometown six years later, now a successful doctor and engaged to be married to a beautiful socialite. He also feels differently about the boy and attempts to gain custody from his aunt and uncle.', 1933, NULL, 68, NULL, 'tt0023849', 5.8, 74.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (722, 'tm154572', 'Mr. Wong in Chinatown', 2, 'A pretty Chinese woman, seeking help from San Francisco detective James Lee Wong, is killed by a poisoned dart in his front hall, having time only to scrawl "Captain J" on a sheet of paper. She proves to be Princess Lin Hwa, on a secret military mission for Chinese forces fighting the Japanese invasion. Mr. Wong finds two captains with the intial J in the case, neither being quite what he seems; there''s fog on the waterfront and someone still has that poison-dart gun...', 1939, NULL, 71, NULL, 'tt0031680', 5.8, 812.0, 1.954, 5.5);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (724, 'tm264908', 'Murder on Lenox Avenue', 2, 'Dramatic events in a Harlem apartment house center around Pa Wilkins, chosen by the Better Business League to replace their ousted, crooked leader Marshall...who wants revenge; and Pa''s ward Jim Bracton, a two-timing Romeo whose affairs are coming to a crisis. And hanging around is Marshall''s murderous junkie henchman, Lomax. Will it all end in someone''s being killed?', 1941, NULL, 65, NULL, 'tt0033929', 5.2, 73.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (725, 'tm112226', 'The Mandarin Mystery', 2, 'Ellery Queen sets out to solve a mystery involving a valuable stamp.', 1936, 3, 66, NULL, 'tt0029207', 5.3, 399.0, 1.283, 4.9);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (726, 'tm87987', 'Stagecoach to Denver', 2, 'Lambert has the stagecoach wrecked killing the Commissioner so his phony replacement can alter Coonskin''s land survey. When Red Ryder exposes the survey hoax, Lambert has his stooge Sheriff put Red in jail.', 1946, 3, 54, NULL, 'tt0038979', 5.7, 164.0, 1.466, 5.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (727, 'tm227367', 'Ferocious Pal', 2, 'A stray German shepherd, a runaway teenage boy, and a runaway teenage girl end up at her uncle''s place in Oregon, where an epidemic of sheep rustling is under way.', 1934, NULL, 50, NULL, 'tt0167155', 4.1, 20.0, 0.6, NULL);
