INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (836, 'tm223770', 'Dixie Jamboree', 2, 'A medicine man on the last show boat on the Mississippi is mistaken by two gangsters as a bootleger, and has to envade them.', 1944, NULL, 72, NULL, 'tt0036762', 4.6, 98.0, 1.187, 4.5);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (837, 'tm5547', 'Come On, Rangers', 2, 'A Texas Ranger (Roy Rogers) and his pals come out of forced retirement to do what the cavalry cannot.', 1938, NULL, 53, NULL, 'tt0030006', 6.2, 112.0, 1.259, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (838, 'tm63806', 'Make a Wish', 2, 'Canary-voiced boy wonder Bobby Breen once more croons his way into our hearts in Make a Wish. While vacationing at a boys'' camp, the rambunctious Breen befriends famed composer Basil Rathbone. Stuck for an inspiration for his latest operetta, Rathbone at last finds it when he meets Breen''s gorgeous mother Marion Claire, a popular singer. Alas, her stiff-necked fiance Ralph Forbes refuses to allow her to return to the stage, whereupon Rathbone spirals into a depression -- and even worse, a profound case of writers'' block. But Little-Mister-Fixit Breen manages to patch up everything just in time for Claire to debut in Rathbone''s latest masterpiece. Offering much-needed comedy relief are Henry Armetta, Leon Errol and Donald Meek as a trio of parasitic would-be songwriters. Make a Wish was based on a story by Gertrude Berg, of "Molly Goldberg" fame.', 1937, NULL, 77, NULL, 'tt0029193', 5.5, 178.0, 1.319, 5.6);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (839, 'tm5379', 'Songs and Saddles', 2, 'An old rancher''s property sites smack-dab on the site where a new highway is to be built, although he doesn''t know it. Someone else does, however, and is determined to force the old man off his property in order to get the ranch for himself. The rancher''s foster son returns home to help the old man keep his property and find out who is behind the scheme to take it from him.', 1938, NULL, 59, NULL, 'tt0169253', 4.8, 49.0, 1.345, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (840, 'tm120566', 'Down to the Sea', 2, 'Greek sponge divers in Tarpon Springs, Florida duel over diving methods and fight over the same girl, and only one will survive.', 1936, NULL, 69, NULL, 'tt0027544', 6.0, 50.0, 0.673, 4.0);
