INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (844, 'tm64601', 'Mule Train', 2, 'A prospector discovers natural cement and suggests it should be used for a new dam. But this is the last thing the badmen of Trail End want, as they have a monopoly of the wagons needed to haul rocks to the site. A pretty sheriff notwithstanding, it''s a job for a singing marshal.', 1950, NULL, 69, NULL, 'tt0042761', 6.6, 101.0, 1.4, 6.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (845, 'tm298782', 'Cheyenne Wildcat', 2, 'Bill Elliot is back as Red Ryder in Cheyenne Wildcat. Also back are Ryder''s perennial cohorts Little Beaver (Bobby Blake, later Robert Blake of Baretta fame) and the Duchess (Alice Fleming). When not pummeling the bad guys, Ryder is the reluctant apex of a love triangle.', 1944, NULL, 56, NULL, 'tt0036707', 6.6, 70.0, 0.662, 4.0);
