INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (884, 'tm300639', 'Hurricane at Pilgrim Hill', 2, 'An elderly man leaves Wyoming to visit his daughter in a small Massachusetts town because, even though she didn''t say so, he believes she needs his help. When he gets there he discovers that his daughter, a lawyer, is under great stress because of her biggest client, an old geezer who is the wealthiest and most powerful man in town. The girl''s father decides to make the old man "disappear" by performing a rain dance he learned from an Indian chief back in Wyoming--and lo and behold it starts to rain and the old man does indeed disappear. The local sheriff, however, suspects foul play and arrests the girl''s father.', 1950, NULL, 60, NULL, NULL, NULL, NULL, 0.841, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (885, 'tm5081', 'Big Town Scandal', 2, 'A crusading editor and his star reporter aid underprivileged youths and crack down on racketeers out to fix basketball.', 1948, 2, 60, NULL, 'tt0040162', 5.4, 85.0, 0.84, 5.0);
