INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (933, 'tm210850', 'Cheers of the Crowd', 2, 'To draw attention to a popular show, a publicity expert hires a former carnival character, not knowing that the man is on the run from the law.', 1935, NULL, 60, NULL, 'tt0026203', 5.7, 34.0, 1.881, 7.0);
