INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (943, 'tm158694', 'Water Rustlers', 2, 'Shirley Martin finds that Weylan has diverted the water from the valley and her cattle are dying. First she and her foreman Bob Lawson go to court. This fails when Weylan''s men keep the ranchers from testifying. But Shirley has a second plan to return water to the valley.', 1939, NULL, 54, NULL, 'tt0032112', 4.8, 86.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (944, 'tm6052', 'Man from Texas', 2, 'James Craig is torn between his criminal career as the masked bandit named the "El Paso Kid," and the life of a law-abiding citizen with his long-suffering wife Zoe. He repeatedly tells Zoe, "just one more time," but he is unable to stop which angers her greatly. However, he does have brief moments of heroics such as when he helps the Widow Weeks save her farm.', 1948, NULL, 71, NULL, 'tt0048343', 5.7, 107.0, 0.963, 6.0);
