INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1026, 'tm113669', 'The Longest Yard', 2, 'In this rough-and-tumble yarn, actually filmed on-location at the Georgia State Prision, the cons are the heroes and the guards are the heavies. Eddie Albert is the sadistic warden who''ll gladly make any sacrifice to push his guards'' semi-pro football team to a national championship.', 1974, 5, 118, NULL, 'tt0071771', 7.1, 18648.0, 9.723, 6.8);
