INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1035, 'tm48521', 'House on Haunted Hill', 2, 'Frederick Loren has invited five strangers to a party of a lifetime. He is offering each of them $10,000 if they can stay the night in a house. But the house is no ordinary house. This house has a reputation for murder. Frederick offers them each a gun for protection. They all arrived in a hearse and will either leave in it $10,000 richer or leave in it dead!', 1959, NULL, 75, NULL, 'tt0051744', 6.8, 26748.0, 10.581, 6.8);
