INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1056, 'tm109759', 'Cockfighter', 2, 'A man who trains fighting cocks vows to remain silent until one of his birds wins a championship.', 1974, 5, 83, NULL, 'tt0071338', 7.0, 2280.0, 2.515, 6.2);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1057, 'tm188577', 'My Name Is Nobody', 2, 'Jack Beauregard, one of the greatest gunman of the Old West, only wants to retire in peace and move to Europe. But a young gunfighter, known as "Nobody", who idolizes Beauregard, wants him to go out in glory. So he arranges for Jack to face the 150-man gang known as The Wild Bunch and earn his place in history.', 1973, 2, 117, NULL, 'tt0070215', 7.3, 26763.0, 9.26, 7.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1058, 'tm150285', 'Boxcar Bertha', 2, '"Boxcar" Bertha Thompson, a transient woman in Arkansas during the violence-filled Depression of the early ''30s, meets up with rabble-rousing union man "Big" Bill Shelly and the two team up to fight the corrupt railroad establishment.', 1972, 5, 88, NULL, 'tt0068309', 6.0, 9488.0, 7.271, 5.9);
