INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1317, 'tm92599', 'Planet of Dinosaurs', 2, 'A spaceship gets lost and is forced to make an emergency landing on an unknown planet. The planet looks much like Earth, only with no trace of civilization. Soon the crew discovers that there are bloodthirsty dinosaurs on the planet. The crew hopes to be found and rescued, but until then, they must fight to survive.', 1977, NULL, 84, NULL, 'tt0078089', 3.8, 1702.0, 2.664, 4.1);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1318, 'tm74755', 'The Lady Vanishes', 2, 'Remake of Alfred Hitchcock''s 1938 classic. On the eve of the Second World War, a train carrying an assortment of passengers, pulls out of a small town in Bavaria. When one of the passengers, a kindly old lady, mysteriously disappears the other passengers are led into confrontation with the Nazis and a desperate race for freedom.', 1979, 2, 97, NULL, 'tt0079428', 6.0, 2686.0, 4.789, 6.0);
