INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1333, 'tm112185', 'The Disappearance of Flight 412', 2, 'Colonel Pete Moore (Glenn Ford) is commander of the Whitney Radar Test Group, which has been experiencing electrical difficulties aboard its aircraft. To ferret out the problem, he sends a four-man crew on Flight 412. Shortly into the test, the jet picks up three blips on radar, and subsequently, two fighters scramble and mysteriously disappear. At this point, Flight 412 is monitored and forced to land by Digger Control, a top-level, military intelligence group that debunks UFO information. The intrepid colonel, kept in the dark about his crew, decides to investigate the matter himself.', 1974, 3, 72, NULL, 'tt0071426', 4.6, 609.0, 4.174, 5.1);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1334, 'tm122152', 'Satan’s Triangle', 2, 'The female survivor of a shipwreck and two Coast Guard helicopter pilots sent to rescue her find themselves trapped in a mysterious part of the ocean known as Satan''s Triangle.', 1979, NULL, 74, NULL, 'tt0073662', 6.0, 1141.0, 5.473, 5.9);
