INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1363, 'tm68833', 'Gamera vs. Barugon', 2, 'Gamera escapes from his rocket enclosure and makes his way back to Earth as a giant opal from New Guinea is brought back to Japan. The opal is discovered to have been an egg that births a new monster called Barugon. The creature attacks the city of Osaka by emitting a destructive rainbow ray from his back, along with a freezing spray capable of incapacitating Gamera.', 1966, NULL, 106, NULL, 'tt0060446', 4.9, 2486.0, 4.946, 6.6);
