INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1395, 'tm81396', 'Operation Atlantis', 2, 'An American agent discovers that the Red Chinese have built a secret atomic city from which they will attempt to invade America.', 1965, 5, 100, NULL, 'tt0058879', 4.8, 100.0, 1.956, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1396, 'tm70041', 'Boy, Did I Get a Wrong Number!', 2, 'The divine Didi, a European actress known more for her bubble bath scenes than for her acting, decides she has had enough with bubble baths and wants to be taken seriously as an actress. So much so that she runs away during the middle of a scene while filming in Hollywood and winds up in Oregon. While she is staying in a hotel, the operator accidentally connects her with a real estate agent named Tom Meade. She asks Tom to bring her some food and when he does he suggests that she go to his cabin in the woods. She also asks him not to tell anyone where she is because she doesn''t want to go back to Hollywood. Now Tom must keep the secret, especially from his wife and from his suspicious housekeeper Lily.', 1966, NULL, 99, NULL, 'tt0060186', 5.4, 1117.0, 1.597, 5.8);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1397, 'ts47033', 'The New 3 Stooges', 1, 'Larry, Moe and Curly Joe bring their mastery of mirth, merriment and mayhem to plenty of places from the Old West to Outer Space and everywhere in between. The hijinks never stop as The Boys bumble and fumble their way from one zany adventure to the next in this animated slapstick series.', 1965, 1, 19, 1.0, 'tt0058832', 7.0, 334.0, 3.11, 10.0);
