INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1490, 'tm198908', 'The Revolutionary', 2, '"A", a member of a student protest organization, becomes disenchanted by his group''s inability to effect real change. Emboldened to pursue more radical methods by the older, experienced leftist organizer Despard, "A" unwittingly becomes party to a labor strike that turns violent. Ultimately held responsible by the authorities for the fracas, "A" allies himself with terrorist Leonard, who intends to avenge those jailed in the protest.', 1970, 5, 100, NULL, 'tt0066296', 5.5, 264.0, 1.996, 5.4);
