INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1492, 'tm132638', 'Tarzan and the Trappers', 2, 'Tarzan goes up against a villian by the name of Schroeder, who is trapping animals and selling them illegally to zoos. A twist is thrown into the plot when Schroeder''s brother, with the help of money-hungry trader Lapin, hunts a different kind of quarry, human game. Now Tarzan must not only fight to save the animals of the jungle, but he must also save himself.', 1958, 3, 70, NULL, 'tt0052273', 4.9, 592.0, 4.115, 4.0);
