INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1506, 'tm133621', 'The Mark of the Hawk', 2, 'The man called Obam struggles with the increasingly hostile forces facing each other in a colonial African country. The African natives want their land and lives back from the British colonists. Obam''s motives are questioned by his own people, in particular his brother Kanda. With the help of his wife Renee and missionary Bruce Craig, will he be able to get things under control before the country self-destructs? Written by Greg Bruno', 1957, NULL, 83, NULL, 'tt0050692', 5.2, 251.0, 0.96, 2.0);
