INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1622, 'tm107266', 'Mixed Company', 2, 'Kathy Morrison (Harris), mother of three, who helps run a "color-blind" adoption program, wants to have another biological child. Her husband, Pete (Bologna), the head coach of the Phoenix Suns, finds out he can''t produce another child. Kathy thinks about adopting a boy, Frederic "Freddie" Wilcox, and Pete does not want to adopt a boy who happens to be black. When he relents, Freddie''s arrival causes an upheaval in the Morrison''s neighborhood, their school, and family. Kathy''s answer is to adopt another child, in this case two, a war-traumatized half-Vietnamese girl, Quan Tran, and a Hopi boy, Joe. The new extended family must now learn to live together.', 1974, 2, 109, NULL, 'tt0071850', 5.7, 228.0, 1.461, 6.0);
