INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1706, 'tm109135', 'On Top of Old Smoky', 2, 'Poachers are harassing toll road owner Jen Larrabee. They want her land because it holds valuable minerals. Autry and the Cass County Boys, mistaken for Texas Rangers, help out.', 1953, NULL, 59, NULL, 'tt0046141', 6.8, 70.0, 0.621, 5.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1707, 'tm772186', 'Sahodari', 2, 'Pazhani has two children — Chandiran and Meena. Meena is married. Chandiran loves Pankajam. His father and grandmother want him to marry a relative girl, Thangam, who is very helpful to the family. But Chandiran marries Pankajam defying them. Although brought in for comic relief, the ever-loveable J. P. Chandrababu and his milkman character became the real irresistible pull of this family melodrama. Director A. Bhimsingh—a rare talent to have successes in both South Indian and Hindi cinemas—masterfully blends lightness and pathos.', 1959, NULL, 175, NULL, 'tt0156989', 5.4, 6.0, 0.6, NULL);
