INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1737, 'ts95763', 'Pinkfong! Halloween Songs', 1, 'It''s time to celebrate Halloween with ghosts and monsters. Let''s sing and dance with monster friends. Meet Pinkfong''s fun, educational videos that captured the hearts of millions of children around the world. Enjoy hundreds of kids'' favorite songs and stories created by educational experts.', 1969, NULL, 1, 3.0, 'tt7818358', 3.6, 5.0, NULL, NULL);
