INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1772, 'tm61843', 'High School Caesar', 2, 'Matt Stevens is the big man at high school. He sweats the students for protection money, acquires copies of tests for a fee, and has rigged the votes so he can beat Kelly in the election for student president. Aside from his anointed acolytes, Matt is almost universally despised. His parents are obscenely rich and spend their time travelling in Europe rather than giving him the parental guidance he needs. Things begin to get ugly when some of the teens resist his power and show Matt up at the drag race.', 1960, NULL, 75, NULL, 'tt0053911', 5.0, 284.0, 0.6, 6.3);
