INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1948, 'ts19439', 'Desmond''s', 1, 'Desmond''s was a British television situation comedy broadcast by Channel 4 from 1989 to 1994. With 71 episodes, Desmond''s became Channel 4''s longest-running sitcom. The first series was shot in 1988, with the first episode broadcast in January 1989. The show was made in and set in Peckham, London, England and featured a predominantly Black British Guyanese cast.
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1949, 'tm160670', 'Island of Fire', 2, 'Someone in a prison run by a corrupt warden fakes the deaths of convicts to later use them as expendable assassins. A police officer is sent into the prison to gather evidence of the corruption.', 1990, 5, 92, NULL, 'tt0099812', 5.7, 3581.0, 8.619, 6.1);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1950, 'tm43527', 'Red River', 2, 'Remake of the 1948 John Wayne feature about a man who rebels against his tyrannical guardian during a crucial cattle drive.', 1988, NULL, 96, NULL, 'tt0095965', 6.2, 299.0, 1.538, 6.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (1951, 'tm137795', 'Big Time', 2, 'Bringing his unique sense of humor to this bizarre and original piece of moviemaking, Tom Waits takes the audience through a musical journey with his jazzy, quirky, bluesy tunes presented as you would never, ever, ever expect.', 1988, 2, 87, NULL, 'tt0094743', 8.0, 832.0, 2.036, 6.7);
