INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2038, 'tm2421', 'A Matter of Sex', 2, 'Dramatization of the true story of the so-called Willmar Eight, a group of Minnesota bank workers who braved freezing conditions whilst picketing their branch in a struggle for union rights.', 1984, NULL, 100, NULL, 'tt0232953', 6.7, 126.0, 1.96, 7.5);
