INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2163, 'tm119033', 'Revolt', 2, 'Rand Martin stars in this tense actioner as a drug runner who decides to turn the tables on his longtime employer -- a powerful druglord and gangster -- by paying him back in piles and piles of revenge. As a means to an end, the ex-drug runner joins forces with a concerned citizen. Together, they dig in deep and attempt to bring the unscrupulous kingpin''s empire to its knees.', 1986, NULL, 72, NULL, NULL, NULL, NULL, 1.438, 5.4);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2164, 'tm796855', 'Insaaf Ki Awaaz', 2, 'Inspector Jhansi is an honest police officer. Her brother Ravi falls in love with her rival''s daughter. When the girl''s father comes to know about his daughter''s relationship, he is enraged.', 1986, NULL, 162, NULL, 'tt0091267', 4.7, 39.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2165, 'tm39221', 'Vijay', 2, 'Vijay is a story about various characters that are bound by relationships of love and friendship. How they become foes and take up weapons against each other. When Arjun and Vicky meet, they are oblivious to the fact that they are cousin brothers.', 1988, 2, 172, NULL, 'tt0096390', 5.3, 250.0, 1.147, 5.3);
