INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2245, 'ts20700', 'Mad About You', 1, 'Young, urban newlyweds Paul and Jamie Buchman try to sustain their marital bliss while sidestepping the hurdles of love in the ''90s.', 1992, 1, 23, 10.0, 'tt0406433', 6.7, 23155.0, 17.895, 6.4);
