INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2247, 'ts37874', 'The Man from Snowy River', 1, 'The Man from Snowy River is an Australian television series based on Banjo Paterson''s poem "The Man from Snowy River". Released in Australia as Banjo Paterson''s The Man from Snowy River, the series was subsequently released in both the United States and the United Kingdom as Snowy River: The McGregor Saga.
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2248, 'tm109512', 'Bound', 2, 'Corky, a tough female ex-convict working on an apartment renovation in a Chicago building, meets a couple living next door, Caesar, a paranoid mobster, and Violet, his seductive girlfriend, who is immediately attracted to her.', 1996, 5, 105, NULL, 'tt0115736', 7.3, 54851.0, 13.463, 7.1);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2249, 'tm55778', 'The Thomas Crown Affair', 2, 'A very rich and successful playboy amuses himself by stealing artwork, but may have met his match in a seductive detective.', 1999, 5, 113, NULL, 'tt0155267', 6.8, 92612.0, 16.222, 6.7);
