INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2622, 'ts246865', 'I''ve Got a Secret', 1, 'Oxygen Network-revival of the classic CBS celebrity panel game show of contestant secrets.', 2000, 7, 29, 1.0, 'tt0233061', 7.3, 15.0, 0.6, NULL);
