INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2658, 'tm19309', 'Living in Fear', 2, 'A man returning to his childhood home for the reading of a will is met with hostility. Do the townsfolk know more about him than his new wife?', 2000, 4, 110, NULL, 'tt0280744', 5.0, 340.0, 1.584, 6.0);
