INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2660, 'tm416466', 'Deadly Family Secrets', 2, 'A New York executive, Martha, witnesses a murder and discovers that the killer is her new brother-in-law. When her sister is nearly killed and her sister''s children kidnapped to silence her, she must unravel the mystery behind the murder to save the kids and see justice served.', 1995, NULL, 95, NULL, 'tt0112825', 4.9, 122.0, 1.592, 3.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2661, 'tm6395', 'Lamhe', 2, 'Viren falls for Pallavi, but she marries Siddharth. The couple dies, leaving behind their daughter, who grows up to look just like her mother and falls in love with Viren.', 1991, 2, 187, NULL, 'tt0102258', 7.2, 2818.0, 1.241, 6.4);
