INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2741, 'tm108440', 'Paradise Park', 2, 'Hope springs eternal in this heartwarming tale about the citizens of a small West Virginia town forced to live in a government-provided trailer park after a devastating flood. As the impoverished flood victims struggle to survive, each resident fantasizes about a better life -- and indeed, a miracle is just around the corner. The film features cameos by country singers Johnny Paycheck, Porter Wagoner and Webb Wilder and wrestler Dusty Rhodes.', 1996, NULL, 101, NULL, NULL, NULL, NULL, 0.6, NULL);
