INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2752, 'tm186028', 'Silent Cries', 2, 'In 1942, the Japanese occupied the island of Singapore. During the take-over, not only military soldiers were taken prisoner, but also innocent civilians, particularly women and children. This is the story of a group of women who band together to face brutal treatment, harsh conditions, and ruthless captors to survive their internment.', 1993, NULL, 120, NULL, 'tt0108134', 6.2, 161.0, 1.512, 1.0);
