INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2775, 'tm54991', 'Oruvan', 2, 'Oruvan is a 1999 Tamil language film directed by Suresh Krishna. The film features Sarathkumar and Pooja Batra in lead roles whilst Devayani, Raghuvaran and Anandaraj play supporting roles. The film was a remake of director''s own Telugu film Auto Driver starring Nagarjuna.', 1999, NULL, 152, NULL, NULL, NULL, NULL, 0.645, 5.0);
