INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2779, 'tm350467', 'Boy Meets Girl', 2, 'Set in Toronto''s Little Italy, Boy Meets Girl stars Sean Astin as Mike, a cynical writer who pens copy for a romance magazine, and Emily Hampshire as Angelina, who has just arrived in Canada from Italy to marry a man she unfortunately doesn''t care for. Mike''s next door neighbor is an eccentric wallpaper hanger who writes poetry in his spare time. Somehow, one of the paperer''s love verses ends up in Angelina''s hands and she''s convinced Mike wrote it -- and suddenly love is in the air and romance is sparked between them.', 1998, NULL, 99, NULL, 'tt0169639', 5.4, 321.0, 2.045, NULL);
