INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2781, 'tm5712', 'Write to Kill', 2, 'In this thriller, Jamie Sanford is murdered by a group of counterfeiters when he attempts to expose them in order to secure an early parole. However, when aspiring writer Clark learns of his brothers death, he sets out to exact revenge and bring the guilty to justice while being framed for his brothers murder.', 1991, 5, 99, NULL, NULL, NULL, NULL, 1.471, 5.7);
