INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (2881, 'ts21434', 'Rake', 1, 'Cleaver Greene is not about politics or morality or even justice. Cleaver Greene is about the law. And it is his passion for the law that drives him to use his formidable intelligence to defend people whom society and the justice system might otherwise convict without a fair trial. He uses his encyclopaedic knowledge of human nature and the Byzantine intricacies of our legal codes to guarantee that his clients get what is theirs by the law; the right to a diligent defence.', 2010, NULL, 55, 5.0, 'tt1587000', 8.5, 7739.0, 15.315, 7.7);
