INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (3371, 'tm59880', 'Mike Birbiglia: What I Should Have Said Was Nothing', 2, 'Mike says, "A few years ago my therapist suggested I keep a journal of all the crazy things that were going on in my life, so that I could keep things in perspective. Around the same time audiences were demanding more material, and I realized that other people might enjoy these stories-so I started sending them out to my mailing list. Now, my Secret Public Journal has become a Comedy Central special and DVD for all the world to see. Not sure this is what my therapist had in mind."', 2008, NULL, 60, NULL, 'tt1188112', 7.6, 1789.0, 4.893, 7.5);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (3372, 'tm136367', 'Recipe for Disaster', 2, 'Rebecca Korda and her two brothers, Sam and Max, are left alone on opening night of their family-owned restaurant.', 2003, 3, 88, NULL, 'tt0198970', 5.7, 11.0, 2.009, 5.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (3373, 'tm115499', 'Deserter', 2, 'Unlikely friends in a melting pot of confusion. Simon Murray fights for the French Foreign Legion. Pascal Dupont fights for himself. War torn men question honour, hope, morality...because you can desert everything...except yourself.', 2002, NULL, 90, NULL, 'tt0313608', 5.3, 1259.0, 5.833, 5.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (3374, 'tm146861', 'Sebastian Live', 2, 'Sebastian Maniscalco''s comedy is impeccably paced and chock-full of seething observations on daily human behavior. He voices his disgust of everything from shopping at discount department stores to men in flip-flops. These hilarious observations have made him one of the most sought-after comedians today. Filmed at the Paramount Theatre in St. Louis, MO, Sebastian Maniscalco Live will leave you screaming for more of Sebastian''s unique brand of humor.', 2009, NULL, 63, NULL, 'tt2450448', 7.5, 214.0, 1.433, 7.0);
