INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (3376, 'tm143140', 'Weather Girl', 2, 'After learning her boyfriend cheated on her with his co-host, a Seattle morning show weather girl  freaks out on-air and is fired. Forced to move in with her little brother and deal with his best friend, she has to learn to cope with being 35, single, unemployed, and unfortunately famous for being the Sassy Weather Girl who lost it on live television.', 2009, 5, 92, NULL, 'tt1085515', 5.8, 3165.0, 5.97, 5.7);
