INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (3378, 'tm130585', 'Chaw', 2, 'A black comedy about the events that are set into motion in a town after a man-eating boar goes on a rampage.', 2009, 5, 117, NULL, 'tt1198396', 5.6, 1153.0, 3.453, 5.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (3379, 'tm28457', 'The Plague', 2, 'Ten years have passed since the world''s children fell into a coma. Tonight they''re waking up and all hell is breaking loose. An unholy battle between the generations is being waged, and time is not on the side of adults.', 2006, 5, 88, NULL, NULL, NULL, NULL, 3.956, 5.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (3380, 'tm78174', 'The Anna Nicole Smith Story', 2, 'Born Vickie Lynn Hogan, she had a son at 18, became a stripper at 20, and married a billionaire at 26. Sheer determination turned her into Anna Nicole Smith, playmate, model and a household name.', 2007, NULL, 83, NULL, 'tt1009012', 4.0, 607.0, 3.653, 4.2);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (3381, 'tm27742', 'My Wife Is A Gangster 3', 2, 'When Aryong, the daughter of a triad boss from Hong Kong is accused of killing the boss of a competing triad, she goes into hiding in Korea. Upon arriving, she is guided by a nimble but loyal Gi-chul and his motley crew, who are assigned to protect her until her return.', 2006, NULL, 115, NULL, 'tt0442795', 6.3, 1627.0, 4.596, 5.8);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (3382, 'ts45140', 'SciGirls', 1, 'SciGirls is a weekly television series and educational outreach program for elementary and middle-school children based on proven best practices for science, technology, engineering and math education for girls. Launched in February 2011 and produced by Twin Cities Public Television, the episodes are broadcast on most PBS stations, and the project’s website is at http://pbskidsgo.org/scigirls. SciGirls is designed to encourage girls to pursue STEM careers, in response to the low numbers of women in many scientific careers..
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (3383, 'tm165702', 'Pot Zombies', 2, 'Radioactive weed turns people into zombies with the munchies for human flesh!', 2005, NULL, 55, NULL, NULL, NULL, NULL, 1.805, 4.8);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (3384, 'tm87001', 'Gracie''s Choice', 2, 'For as long as she can remember, 16 year-old Gracie has been raising her four siblings, each of whom has a different, absent father and their mother is on the fast track to self-destruction. When these children''s lives are about to be pulled apart, Gracie will have to do the impossible and make the ultimate sacrifices to keep her family together.', 2004, NULL, 90, NULL, 'tt0395565', 7.4, 3581.0, 6.196, 7.1);
