INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4127, 'ts20437', 'Magic City', 1, 'Set in 1959 Miami, Florida shortly after the Cuban Revolution, Magic City tells the story of Ike Evans, the owner of Miami''s most glamorous hotel, the Miramar Playa. Evans is forced to make an ill-fated deal with Miami mob boss Ben Diamond to ensure the success of his glitzy establishment.', 2012, 11, 52, 2.0, 'tt0483857', 7.7, 12605.0, 11.947, 6.8);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4128, 'ts20389', 'Primeval: New World', 1, 'A North American spin-off of the hit U.K. television series, Primeval: New World follows a specialized team of animal experts and scientists that investigates the appearance of temporal anomalies and battles both prehistoric and futuristic creatures.', 2012, 8, 45, 1.0, 'tt2295955', 6.5, 4565.0, 13.861, 6.6);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4129, 'ts34845', 'The Paradise', 1, 'An intoxicating love story set in England''s first department store in the 1870s. The Paradise revolves around the lives of the people who live and work in the store, each bound in their own way by the power of the world they live in, and the pasts that follow them there. A love story, mystery, and social comedy all in one.
