INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4143, 'tm72100', 'Beasts of the Southern Wild', 2, 'Hushpuppy, an intrepid six-year-old girl, lives with her father, Wink in ''the Bathtub'', a southern Delta community at the edge of the world. Wink’s tough love prepares her for the unraveling of the universe—for a time when he’s no longer there to protect her. When Wink contracts a mysterious illness, nature flies out of whack—temperatures rise, and the ice caps melt, unleashing an army of prehistoric creatures called aurochs. With the waters rising, the aurochs coming, and Wink’s health fading, Hushpuppy goes in search of her lost mother.', 2012, 4, 91, NULL, 'tt2125435', 7.2, 83033.0, 9.219, 6.8);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4144, 'tm37884', 'Red Tails', 2, 'The story of the Tuskegee Airmen, the first African-American pilots to fly in a combat squadron during World War II.', 2012, 4, 125, NULL, 'tt0485985', 5.9, 35424.0, 47.974, 6.5);
