INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4148, 'tm35437', 'The Collection', 2, 'Arkin escapes with his life from the vicious grips of "The Collector" during an entrapment party where he adds beautiful Elena to his "Collection." Instead of recovering from the trauma, Arkin is suddenly abducted from the hospital by mercenaries hired by Elena''s wealthy father. Arkin is blackmailed to team up with the mercenaries and track down The Collector''s booby trapped warehouse and save Elena.', 2012, 5, 82, NULL, 'tt1769361', 6.1, 49159.0, 21.406, 6.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4149, 'ts27936', 'Mr. D', 1, 'Based on Gerry Dee''s real-life experiences as a high school teacher before he switched to comedy full-time, MR. D is a story about a charming, under-qualified teacher trying to fake his way through a teaching job, just like he often fakes his way through life.', 2012, 8, 21, 8.0, 'tt2128016', 2.3, 15.0, 3.287, 8.1);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4150, 'tm34714', 'Iron Sky', 2, 'In the last moments of World War II, a secret Nazi space program evaded destruction by fleeing to the Dark Side of the Moon. During 70 years of utter secrecy, the Nazis construct a gigantic space fortress with a massive armada of flying saucers.', 2012, 5, 110, NULL, 'tt1034314', 5.9, 93718.0, 33.021, 5.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4151, 'ts35428', 'The Secret of Crickley Hall', 1, 'A year after the disappearance of their son, Gabe and Eve Caleigh and their two daughters attempt to start anew, they head to Crickley Hall - a seemingly perfect countryside house. But when cellar doors start to open on their own, phantom children''s cries are heard through the night and a frenzied cane-wielding specter rears its head - the Caleigh''s realize the house comes with a lot more than they bargained for. Just as they''re ready to move out, Eve Caleigh hears Cam''s cries and all bets are off.', 2012, 8, 58, 1.0, 'tt2294227', 6.8, 3028.0, 5.383, 7.3);
