INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4153, 'ts33254', 'Injustice', 1, 'On the surface William Travers is a picture of success. An accomplished criminal barrister happily living with his wife in rural Suffolk. However, Travers is still recovering from a traumatic series of events that have shaken his belief in the legal system.
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4154, 'ts79640', 'The Crusades', 1, 'This three-part series sheds new light and new perspective on the 200-year war between Christians and Muslims for control of the Holy Land.', 2012, 1, 52, 1.0, 'tt2200679', 7.0, 128.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4155, 'tm43657', 'A Thousand Words', 2, 'Jack McCall is a fast-talking literary agent, who can close any deal, any time, any way. He has set his sights on New Age guru Dr. Sinja for his own selfish purposes. But Dr. Sinja is on to him, and Jack’s life comes unglued after a magical Bodhi tree mysteriously appears in his backyard. With every word Jack speaks, a leaf falls from the tree and he realizes that when the last leaf falls, both he and the tree are toast. Words have never failed Jack McCall, but now he’s got to stop talking and conjure up some outrageous ways to communicate or he’s a goner.', 2012, 4, 91, NULL, 'tt0763831', 5.9, 42197.0, 33.408, 6.1);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4156, 'tm33936', 'Get the Gringo', 2, 'A career criminal nabbed by Mexican authorities is placed in a tough prison where he learns to survive with the help of a 9-year-old boy.', 2012, 5, 96, NULL, 'tt1567609', 6.9, 107473.0, 41.456, 6.5);
