INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4159, 'tm45822', 'Paranormal Activity 4', 2, 'It has been five years since the disappearance of Katie and Hunter, and a suburban family witness strange events in their neighborhood when a woman and a mysterious child move in.', 2012, 5, 97, NULL, 'tt2109184', 4.6, 65750.0, 23.469, 5.4);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4160, 'ts27877', 'Public Enemies', 1, 'Public Enemies explores the relationship between 28-year-old Eddie, recently released on life licence from prison after serving 10 years, and his probation officer, Paula, returning from suspension following a shocking crime committed by an offender under her supervision.', 2012, NULL, 60, 1.0, 'tt2148433', 7.0, 708.0, 1.634, 7.5);
