INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4432, 'tm346523', 'Snoop Dogg Presents The Bad Girls of Comedy', 2, 'Hip hop superstar and longtime comedy aficionado Snoop Dogg presents his picks for the most outrageous, hilarious comediennes in this standup showcase featuring Tiffany Haddish, April Macie, Cookie Hull (Simply Cookie), Monique Marvez and Luenell.', 2012, 5, 60, NULL, 'tt2400435', 7.0, 101.0, 0.899, 7.5);
