INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4604, 'ts34377', 'The Village', 1, 'The Village tells the story of life in a Derbyshire village through the eyes of a central character, Bert Middleton.', 2013, 8, 59, 2.0, 'tt2394340', 7.7, 2229.0, 7.29, 7.6);
