INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4861, 'tm141552', 'New Initial D the Movie - Legend 1: Awakening', 2, 'The first movie in a trilogy, focusing on the battle against the Takahashi brothers. High school student Takumi Fujiwara works as a gas station attendant during the day and a delivery boy for his father''s tofu shop during late nights. Little does he know that his precise driving skills and his father''s modified Toyota Sprinter AE86 Trueno make him the best amateur road racer on Mt. Akina''s highway. Because of this, racing groups from all over the Gunma prefecture issue challenges to Takumi to see if he really has what it takes to be a road legend.', 2014, NULL, 62, NULL, 'tt3971764', 7.4, 307.0, 19.938, 8.2);
