INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (4890, 'tm155242', 'Pants on Fire', 2, 'Jack Parker has always skated by on his lies, especially the one about Mikey, an underprivileged (and made-up) teen who Jack "tutors"... until one day "Mikey" shows up for real, and all Jack''s lies start coming true.', 2014, NULL, 85, NULL, 'tt3826338', 5.1, 1079.0, 7.08, 5.5);
