INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (5510, 'tm244602', 'High Strung', 2, 'When a hip hop violinist busking in the New York subway encounters a classical dancer on scholarship at the Manhattan Conservatory of the Arts, sparks fly. With the help of a hip hop dance crew they must find a common ground while preparing for a competition that could change their lives forever.', 2016, 3, 96, NULL, 'tt3451230', 6.3, 9134.0, 11.956, 7.1);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (5511, 'tm408122', 'All at Once', 2, 'A young up and coming artist in New York city has his life and dreams forever altered when the tragic events of 9/11 take the lives of his two best friends and he accepts guardianship of the couple''s two young daughters. Now eleven years later, and teaching art at an elementary school, he raises the girls as if they were his own, but the financial grind to live in NYC is too much, so he decides to take the girls away from the only place they''ve ever called home and move back to Buffalo where he grew up. This "non-traditional" family now faced with change, new surroundings, and a new journey, must learn how to adjust to this new life, while trying to find themselves along the way.', 2016, NULL, 112, NULL, 'tt5073756', 5.9, 371.0, 3.643, 5.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (5512, 'tm205374', 'Band of Robbers', 2, 'A comedic thriller that re-imagines Mark Twain''s iconic literary characters of "Huckleberry Finn" and "Tom Sawyer" as grown men in current day.', 2016, NULL, 95, NULL, 'tt4421614', 6.0, 4251.0, 7.337, 6.1);
