INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (5550, 'tm206403', 'Silverhide', 2, 'A group of conspiracy theorists watches a top-secret military base in the desolate Welsh mountains.', 2015, NULL, 79, NULL, 'tt2780588', 2.4, 177.0, 1.926, 2.3);
