INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (5850, 'ts95819', 'Car Patrol of Car City', 1, 'Mat the police car and Franck the fire truck are the fearless detectives of the Car Patrol. Every time a vehicle in Car City gets into a trouble, the Car Patrol is there to make sure that everyone is safe. Join the Car Patrol in solving the mysteries of Car City.', 2016, NULL, 12, 3.0, 'tt13301368', 6.5, 38.0, NULL, NULL);
