INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6156, 'ts58302', 'Killing Eve', 1, 'A security consultant hunts for a ruthless assassin. Equally obsessed with each other, they go head to head in an epic game of cat-and-mouse.', 2018, 8, 42, 4.0, 'tt7016936', 8.2, 112967.0, 45.175, 8.1);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6157, 'ts12314', 'American Gods', 1, 'An ex-con becomes the traveling partner of a conman who turns out to be one of the older gods trying to recruit troops to battle the upstart deities. Based on Neil Gaiman''s fantasy novel.', 2017, 11, 54, 3.0, 'tt1898069', 7.7, 84311.0, 54.759, 7.1);
