INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6159, 'ts80908', 'A Very English Scandal', 1, 'It''s the late 1960s, homosexuality has only just been legalised and Jeremy Thorpe, the leader of the Liberal party, has a secret he''s desperate to hide.', 2018, 8, 56, 1.0, 'tt6938856', 7.7, 13303.0, 8.596, 7.4);
