INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6265, 'tm463048', 'The Fare', 2, 'When a charming fare named Penny climbs into his taxi cab, Harris, her world-weary driver, finds himself engaged in the only kind of courtship he can have with a passenger -- one that lasts as long as her trip. That is, right up until she disappears from the back seat without a trace. When confusion gives way to reality, he resets his meter and is instantaneously transported back to the moment when she climbed into his cab. As he and Penny find themselves trapped in an endless nighttime cab ride, with only each other for company, secrets will be revealed, truths will come to light, and Harris'' entire life will be changed forever.', 2018, NULL, 82, NULL, 'tt7293920', 6.2, 2580.0, 4.249, 6.6);
