INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6297, 'tm266712', 'Wonderstruck', 2, 'The story of a young boy in the Midwest is told simultaneously with a tale about a young girl in New York from fifty years ago as they both seek the same mysterious connection.', 2017, 2, 115, NULL, 'tt5208216', 6.2, 10195.0, 13.194, 6.1);
