INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6302, 'tm322148', 'Dark River', 2, 'After her father dies, a young woman returns to her Yorkshire village for the first time in 15 years to claim the family farm she believes is hers.', 2018, NULL, 90, NULL, 'tt5700176', 5.8, 3839.0, 5.515, 5.8);
