INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6305, 'ts81544', 'All or Nothing: New Zealand All Blacks', 1, 'Behind-the-scenes series following the New Zealand All Blacks rugby team throughout 2017, taking an in-depth look at the players and coaches on and off the field.', 2018, 11, 43, 1.0, 'tt8169088', 8.1, 985.0, 2.694, 4.4);
