INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6353, 'ts53721', 'Revenge Body With Khloe Kardashian', 1, 'By gaining confidence and control over their lives, maybe even for the first time, Khloé Kardashian and a team of Hollywood''s best trainers and glam squads help two individuals per episode re-create themselves.', 2017, 8, 45, 3.0, 'tt6410966', 3.5, 602.0, 8.504, 7.6);
