INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6379, 'tm219283', 'In Dubious Battle', 2, 'In the California apple country, 900 migratory workers rise ''in dubious battle'' against the landowners. The group takes on a life of its own—stronger than its individual members, and more frightening. Led by the doomed Jim Nolan, the strike is founded on his tragic idealism—''courage, never submit, or yield''.', 2017, 5, 110, NULL, 'tt4412496', 6.0, 4026.0, 15.731, 5.9);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6380, 'tm415051', 'In My Mind', 2, 'The film recounts one of Chris'' early filmmaking experiences: an attempt to interview Patrick McGoohan - something McGoohan had resisted previously - about his enigmatic series for a Channel 4 commissioned documentary. A documentary that didn''t quite go to plan. In a series of frank interviews conducted by Chris, most of which ultimately remained unused in the 1983 documentary ''Six Into One-The Prisoner File'', McGoohan slowly reveals his innermost thoughts about his concept.', 2017, NULL, 79, NULL, 'tt7387632', 7.3, 93.0, 0.858, 7.6);
