INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6425, 'tm447091', 'The Ringmaster', 2, 'Nationwide quietness. The streets are empty. Everyone’s glued to their screens at home, watching the final game. In the outskirts of Denmark, close to the German border, a small gas station needs to be open for service, even on this special night.  Two young women have the shift. Ambitious Agnes is in the backroom putting finishing touches on her thesis, while free-spirited Belinda is on her phone, hoping to get the attention of her boyfriend. Unfortunately, the shift is not going to be as uneventful as they think, because no customers also means no witnesses, and the girls have been spotted to play a special part in a very different sort of game.', 2018, NULL, 100, NULL, 'tt9060062', 4.7, 544.0, 4.393, 6.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6426, 'tm312100', '2 pigeons', 2, 'An oily, amoral estate agent is preyed upon by one of his victims, who quietly moves into his flat and, unseen, begins a deliciously malicious campaign of revenge.', 2017, NULL, 80, NULL, 'tt5532370', 5.5, 1161.0, 3.332, 5.3);
