INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6591, 'tm266730', 'Astral', 2, 'A detached university student faces the consequences of astral projection when he uses it to reconnect with his dead mother.', 2018, NULL, 83, NULL, 'tt4765240', 4.9, 4627.0, 5.326, 4.6);
