INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6593, 'tm424714', 'Bad Ben - The Mandela Effect', 2, 'In 2016 the horror Tom Riley experienced in a home he bought at a Sheriff''s Sale was captured on 21 security cameras in the home. What if he was experiencing this over and over again in parallel universes? Bad Ben - The Mandela Effect, gathers footage together that shows the paranormal experiences Tom had, seem to keep occurring.', 2018, NULL, 67, NULL, NULL, NULL, NULL, 1.607, 4.2);
