INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6623, 'tm446482', 'Change in the Air', 2, 'A peaceful community is forever changed when a mysterious young woman moves in. As the quirky locals embrace her, their lives soon improve. But, they can''t help notice that their strange new neighbor has a secret.', 2018, 2, 94, NULL, 'tt5013782', 5.7, 671.0, 3.697, 5.5);
