INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6625, 'ts57163', 'The iDOLM@STER.KR', 1, 'THE IDOLM@STER.KR, set in the world of Korean entertainment production, stars Korean idols of course, as well as other Japanese and Thai hopefuls. Like the original game, the drama follows a group of young women as they embark on a career in the entertainment industry, and depicts their sweat and tears, their hopes and dreams.', 2017, NULL, 45, 1.0, 'tt7256442', 6.9, 42.0, 3.38, 7.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6626, 'tm316791', '3 Hours till Dead', 2, 'An AWOL soldier with PTSD goes into hiding along with his brother and a few friends. They retreat into a rural farm area unaware that the outside world has ceased to function. On their way back to civilization, his brother is attacked by an infected farmer. He quickly morphs into a rabid animal and lives for exactly three hours. Realizing they are in grave danger, they head back to the forest trying to outlive the legions of the infected.', 2017, NULL, 79, NULL, 'tt4854820', 4.1, 198.0, 2.361, 4.7);
