INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6629, 'tm364840', 'Division 19', 2, 'In 2039, jails have been turned into online portals where the public gets to choose what prisoners eat, wear, watch and who they fight. So successful is Panopticon TV, it is about to be rolled out to a whole town, providing subscribers even more choice.', 2017, NULL, 93, NULL, 'tt2492344', 5.0, 2582.0, 4.197, 5.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6630, 'tm416271', 'Another Soul', 2, 'A couple on the run battle to save their daughter from possession by a demon.', 2018, NULL, 78, NULL, 'tt5165620', 2.2, 291.0, 4.868, 4.7);
