INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6639, 'ts77813', 'Pushpavalli', 1, 'Pushpavalli was supposed to finish her Food Science degree and marry a Brahmin man that her mother approved of. All that changed after meeting the charming Nikhil Rao. After secretly following him to Bangalore, she juggles working at a children’s library, dealing with her unpredictable landlady, all the while trying to convince herself that it’s not stalking if you know the person, right?', 2017, NULL, 24, 2.0, 'tt7675948', 7.4, 1568.0, 2.598, 5.4);
