INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6643, 'tm423298', 'Karwaan', 2, 'Avinash, a dejected soul stuck in a dead-end job shares a strange relationship with his father. He holds him responsible for crushing his dreams. However, he is left pondering upon this longstanding hatred when he hears of his father’s untimely demise.', 2018, NULL, 125, NULL, 'tt7919680', 7.6, 15284.0, 2.54, 7.2);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6644, 'tm322902', 'Ripped', 2, 'Two free-spirited stoners find themselves catapulted into 2016 after smoking some top secret pot created by the CIA in 1986. With 30 years of their lives lost, these now balding and overweight friends use their uncomplicated enthusiasm to get their lives back on track and figure out the modern world.', 2017, NULL, 97, NULL, 'tt4876952', 4.7, 1832.0, 2.722, 4.9);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6645, 'tm447239', 'Dennis Miller: Fake News, Real Jokes', 2, 'Five-time Emmy award winner Dennis Miller takes on the current climate like no other can in Fake News, Real Jokes! From selfies and airline travel to Trump and journalists, he delivers his signature critical assessments in his low key style that has been deemed by The Hollywood Reporter as "the most cerebral, astute and clever standup ever".', 2018, NULL, 58, NULL, 'tt8618716', 5.8, 224.0, 0.883, 7.0);
