INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6666, 'tm443643', 'Make Us Dream', 2, 'Steven Gerrard became perhaps the greatest player in the history of Liverpool FC, but did so when success and trophies were declining. It became his personal mission to lift the famous club back to the top. That loyalty raised him to God-like status with Liverpool fans, but was an unbearable burden, bringing with it a profound sense of responsibility to live up to their and his own expectations.', 2018, NULL, 104, NULL, 'tt9206562', 7.9, 3036.0, 4.89, 8.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6667, 'tm368034', 'Maya the Bee: The Honey Games', 2, 'When an overenthusiastic Maya accidentally embarrasses the Empress of Buzztropolis, she is forced to unite with a team of misfit bugs and compete in the Honey Games for a chance to save her hive.', 2018, 3, 85, NULL, 'tt6685596', 5.6, 861.0, 15.95, 6.8);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6668, 'tm828733', 'The Road to Independence', 2, 'To discover more of the story of its Independence, Olie Hunter Smart takes on an immense challenge to walk the length of India, a 4,500km journey over seven months seeking out untold stories of Independence and Partition. Olie''s route takes him over grueling snowy mountain passes high up in the Himalayas, battling intense heat in the northern plains, and being drenched to the bone by monsoon rains as he walks through the rural heartland of the country. Following in Gandhi''s footsteps, Olie immerses himself in the culture, being invited in by so many of the wonderful people he encounters, recording shocking and heartfelt first-hand accounts of India''s struggle for freedom gained 70 years earlier.', 2018, NULL, 57, NULL, 'tt10826016', NULL, NULL, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6669, 'tm1069187', 'Milgram and the Fastwalkers', 2, 'A world-class psychiatrist takes on a new patient who is experiencing strange dreams, and is reluctantly drawn into the dark world of aliens and UFOs.', 2018, NULL, 109, NULL, 'tt15213620', 2.5, 22.0, 0.6, 10.0);
