INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6775, 'tm876060', 'Arctic Daughter: A Lifetime of Wilderness', 2, 'Arctic Daughter: A Lifetime of Wilderness is the second documentary by Jean Aspen and Tom Irons. Recorded at their cabin in Alaska''s remote Brooks Range, it layers historic footage, vivid photos and video and original music to portray Aspen''s amazing life. Born to explorer parents, Connie and Bud Helmericks, Jeanie began life in arctic wilds. At twenty-two, she and a friend set off on the Yukon River for a year alone. This lyrical odyssey across seven decades celebrates the art of following one''s dreams beyond a beaten trail.', 2018, NULL, 86, NULL, 'tt11656656', 7.1, 50.0, 1.987, NULL);
