INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6808, 'tm412098', 'The Trough', 2, 'Yu Chau is a cop who has gone so deep undercover within the triad. He can no longer tell which side of the law he''s on. When he accidentally kills one of his pals in an operation, he runs off into the boonies to lick his wounds. Upon his return, he teams up with fellow officers Jim and Jackie to catch a triad Boss, only to unveil collusion with government officials at the highest level. Yu Chau once again faces the dilemma of taking the law into his own hands...', 2018, NULL, 113, NULL, 'tt6871634', 4.6, 274.0, 2.081, 6.4);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6809, 'tm413115', '6-Headed Shark Attack', 2, 'What is supposed to be a marriage boot camp on a remote island turns into the ultimate test for survival when a 6-headed shark starts attacking the beach. Trapped with minimal weapons they try to fight off the shark, but quickly discover that no one is safe in the water or on land.', 2018, NULL, 89, NULL, 'tt8360902', 2.8, 1169.0, 11.854, 4.4);
