INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6922, 'tm434786', 'Whatever Father!', 2, 'Matías, a 10-year-old boy, runs away from home in a rage and ends up getting on a bus to anywhere, until he is found by Rogelio, a 40-year-old man who works as a restaurant clown.', 2018, NULL, 102, NULL, 'tt8461794', 4.8, 51.0, 1.828, 4.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6923, 'tm311531', 'From Japan to Egypt', 2, 'Muharram falls in love with a Japanese diplomat named Sakura, they get married and have twins.  But she returns to Japan with the kids without his knowledge because of the difficult living conditions. Seven years later, they reach an agreement that the children come for six months to stay with him, but under conditions.', 2017, 3, 100, NULL, NULL, NULL, NULL, 0.853, 6.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6924, 'tm373736', 'First We Take Brooklyn', 2, 'An ex-felon joins an Israeli crime syndicate in Brooklyn.', 2018, 5, 90, NULL, 'tt5673714', 3.9, 569.0, 6.116, 4.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6925, 'tm432901', 'Mitron', 2, 'Jai (Jackky Bhagnani), born and brought up with middle-class values, has a ‘take it easy’ approach to life. Since he doesn''t believe in herd mentality, he and his two best friends, Raunak (Pratik Gandhi) and Deepu (Shivam Parekh) start looking for unique ways to make it big in the world. During this trial and error phase, Jai realizes his dream. But his decision of choosing an unprofitable career path doesn’t go down too well with his father (Neeraj Sood), who has bigger aspirations for him. Therefore, in order to bring stability in his life, his father decides to get him married. Destiny, however, has something else in store for Jai, when he accidentally meets Avni (Kritika Kamra), an ambitious, MBA graduate, who wants to start her own business. Set in the backdrop of the Gujarati milieu, the film traces Jai and Avni’s personal journey, as they both find themselves and discover the true meaning of friendship in the bargain.', 2018, NULL, 116, NULL, 'tt8852558', 6.9, 2507.0, 2.805, 6.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6926, 'tm424950', 'Thomas & Friends: Big World! Big Adventures! The Movie', 2, 'Thomas leaves Sodor to fulfil his dream of seeing the world. This heroic quest takes Thomas across deserts, through jungles and over dangerous mountains as he travels across five continents seeing sights he has never seen before.', 2018, NULL, 80, NULL, 'tt7415466', 5.4, 275.0, 3.797, 7.5);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6927, 'tm815913', 'Republic Z', 2, 'Two friends trying to survive in a post apocalyptic world with zombies.', 2018, NULL, 87, NULL, 'tt10468080', 5.2, 9.0, NULL, NULL);
