INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (6929, 'ts79019', 'Shaitaan Haveli', 1, 'B-Grade filmmaker Hariman shows up to shoot his horror film at an old haveli. Freak occurrences make the crew realise that they''re not just shooting a horror film but are soon going to be living one.', 2018, NULL, 24, 1.0, 'tt7612938', 7.2, 822.0, 2.271, 4.0);
