INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7035, 'tm349238', 'Deathgrip', 2, 'For the last two years, Fairclough and Porter have traveled to every inhabited continent on the planet with a simple goal: to show the world a new vision of mountain biking. Joined on this quest by a collection of the most progressive and influential riders that this generation of mountain biking has to offer, Fairclough and Porter have embarked on an all-out assault on the bleeding edge of the sport''s limits. DEATHGRIP is a relentless mission to challenge the limits of creativity, technology, and the human potential. DEATHGRIP is a creative oasis for Fairclough and Porter - a place where the raw expression of Fairclough''s riding ability is captured with the most progressive filmmaking technology against the backdrop of the most visually engaging locations in the world. The future is now. #DEATHGRIPMOVIE', 2017, NULL, 53, NULL, 'tt7046112', 6.3, 157.0, 1.028, 8.5);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7036, 'tm371825', 'Mistress', 2, 'On an estate full of secrets, a rigid matriarch demands her newest daughter-in-law to provide a grandson to preserve her family''s lineage of nobility.', 2017, NULL, 98, NULL, 'tt5094886', 6.2, 115.0, 0.6, NULL);
