INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7109, 'tm439819', 'Mùa Viết Tình Ca', 2, 'To flee a public scandal, a humiliated musician hides in a seaside town where he meets a fiery bartender who sparks more than creative inspiration.', 2018, NULL, 107, NULL, 'tt9076868', 6.2, 20.0, 0.603, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7110, 'tm510320', 'Musclecar', 2, 'Bambi Steele is about to make her first film. But with the only money she has Bambi buys her dream car a 1968 V8 Dodge Phoenix. She tells her cast the film is off. Unable to run her newly acquired muscle car, and at risk of losing it she enlists brother Bucks help. Bambi turns to her dark side when she finds a way to both run her car and bring it to life in the pages of a book. Using voodoo, Bambi needs blood, an OX heart and eight human souls to achieve the impossible. Enter Randy Bambi''s leading man and he is besotted by the Femme Fatale. Together they kill her cast one by one and put the blood in the car. When Randy threatens to destroy the car and spill the beans to the cops. Buck steps in to save the day and soon Randy is fed to the beast. In the end Bambi will pay the ultimate price in an all out voodoo onslaught that will bring her Frankenstein monster to life.', 2017, NULL, 77, NULL, 'tt7680690', 4.8, 47.0, 1.545, 6.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7111, 'tm411032', 'Villavan', 2, 'A young man takes on the role of a vigilante and goes out to hunt his father''s murderer. This ongoing search eventually leads him to unexpected surprises.', 2018, NULL, 120, NULL, 'tt8537758', 6.5, 12.0, 0.601, NULL);
