INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7118, 'tm403575', 'Drinksgiving', 2, 'Post-grad Sarah is going to have her first ‘grown-up’ party on one of the biggest party nights of the year, the night before Thanksgiving. Sarah soon finds out that growing up is not all she thinks it is as she finds out how much, and, how little, her friends have changed.', 2018, NULL, 89, NULL, 'tt6158388', 4.1, 138.0, 2.611, 3.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7119, 'tm528248', '2nd Chances', 2, 'The director, Dav Lewis, started a nonprofit, 2ndchances.Life that provides help for men/women re-entering society after incarceration. The film sheds light on the harsh reality of the Texas Criminal Justice System through the lives of men and children who have been affected a small town (Terrell, TX.) 30 minutes east of Dallas. In addition to showing the many challenges the system has on the entire community, specifically the African Americans, the film also shows it''s possible to achieve entrepreneurship as a former felon. The film is raw, real, emotional, yet inspiring. The film is not meant to entertain but to educate, promote change, and most of all empower people to live more purposely.', 2017, NULL, 80, NULL, 'tt6522444', NULL, NULL, NULL, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7120, 'tm325459', 'Doug Stanhope: The Comedians'' Comedian''s Comedians', 2, 'Doung Stanhope has traveled the world and made himself a real comedian''s comedian, check him out with comedians'' comedian''s comedians Brendon Walsh, Morgan Murphy, and Glenn Wool in this comedy special shot during Austin, TX''s South by Southwest.', 2017, NULL, 61, NULL, 'tt6678722', 6.3, 128.0, 1.923, 7.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7121, 'ts105217', 'Pinkfong! Dinosaur Songs', 1, 'Shake it! Shake it! Sing and move your body with awesome dinosaurs and learn their names. Meet Pinkfong''s fun, educational videos that captured the hearts of millions of children around the world. Enjoy hundreds of kids'' favorite songs and stories created by Pinkfong, the official creator of global hit Baby Shark behind #BabySharkChallenge.', 2017, NULL, 1, 2.0, 'tt9134714', NULL, NULL, NULL, NULL);
