INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7244, 'tm463848', 'Sunny', 2, 'Based in the early 90s in Washington DC, this film tells the heartfelt life story of a girl named "Sunny". Like many young girls growing up in an urban community, with the lack of family, Sunny is forced to fend for herself in the violent and rugged streets of DC. Several connected households reveal a highly anticipated ending.', 2018, NULL, 115, NULL, 'tt9033432', 4.6, 60.0, 0.719, NULL);
