INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7280, 'tm887174', 'White Wolves: Ghosts of the Arctic', 2, 'We follow a pack of wolves on Ellesmere Island, in Canada’s far north, as they struggle to raise their pups in the brief arctic summer. Hidden in her den, the alpha female of the pack gives birth to a new generation. Time is of the essence: her pups need to grow quickly and they have much to learn if they are to survive the merciless winter ahead.', 2017, NULL, 43, NULL, NULL, NULL, NULL, 0.733, NULL);
