INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7283, 'tm335968', 'Caim', 2, 'A girl wakes up tied up to a chair in a room with a man she does not know. She has no recollection of what happened, or how she came to be where she is. Through dreams, visions, and memories she attempts to remember and escape her current predicament.', 2017, NULL, 83, NULL, 'tt14545150', 6.1, 14.0, 0.6, NULL);
