INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7285, 'ts96439', 'Out on Stage', 1, 'The Dekkoo-original series ''OUT On Stage'' is a hilarious, one-of-a-kind comedy series hosted by Zach Noe Towers - OUT Magazine''s "One of the 10 comedians to watch in 2018". Experience the party when Zach and 16 other top-rated Gay and Lesbian stand-up comedians discuss taboo subjects as only they can.', 2018, NULL, 34, 1.0, 'tt7638682', 5.2, 5.0, 0.637, NULL);
