INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7295, 'tm325854', 'Yevanavan', 2, 'Akhil shoots his girlfriend Nayana on camera while she is taking bath. Nayana finds about it and gets furious. Though Akhil deletes the video immediately, he later recovers it with the help of a recovery software as he wants to enjoy Nayana taking bath. The mobile gets lost and it travels via many pairs of hands. Finally Saran, a software professional, gets it. Akhil traces it and asks Saran to give back his mobile; Saran, who know about the bathing video contained in the mobile phone, puts a few demands to give it back. He wants Akhil to do certain things. What are the things demanded by Saran? Could Akhil do them and get his mobile back? Does Nayana know all these things? What happened to the love? Watch the movie to know the answers.', 2017, NULL, 131, NULL, 'tt7951436', NULL, NULL, 0.6, 7.3);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7296, 'ts236619', 'Loo Loo Kids Johny & Friends Musical Adventure', 1, 'Music-loving baby Johny goes on dance-filled adventures with his family, friends and adorable critters in this colorful, animated preschooler series. Watch all you want.', 2018, 7, 3, 1.0, NULL, NULL, NULL, 1.168, 10.0);
