INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7301, 'tm441181', 'And There Were 4', 2, 'Joel, an actor who plays a superhero named, Thrill  finds his life in turmoil when a disagreement forces him to leave his home. While Joel reunites with old friends, his fictional character Thrill is forced to make tough decisions as his partner, Scholar sets out to locate superhuman twins: Shift and Militant.  The story will take the viewer on a journey as the lives of fictional Thrill and reality based Joel begin to become interwoven as they each encounter completely different individuals with interconnecting journeys of relationships, love, drama and race with both fiction and reality colliding in the end', 2018, NULL, 83, NULL, 'tt7385782', 4.6, 58.0, 0.6, 9.0);
