INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7326, 'tm426072', 'Auf Ediths Spuren', 2, 'A documentary about the Austro-British photographer Edith Tudor-Hart, Tracking Edith follows filmmaker Peter Stephan Jungk’s journey to understand the motivations of his great aunt who, while living a double life as a spy for the KGB, recruited Kim Philby and helped create the Cambridge Five, the Soviet Union’s most successful spy ring in the United Kingdom, which infiltrated the very top of British intelligence (and inspired John le Carré’s Tinker Tailor Soldier Spy). As Jungk learns more about his aunt and her work, his film demands the question: why is she not recognized alongside Kim Philby and the Cambridge Five as one of the spies that changed the world?', 2017, NULL, 91, NULL, 'tt5869550', 7.2, 41.0, 0.6, NULL);
