INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7367, 'tm502136', 'Attention Please', 2, 'My son was diagnosed with ADHD aged 5; the only option being given to me was medication. I knew deep down they were wrong, but I didn''t have an alternative to fight them with...until I met Bob. Neuro Developmental Therapist, Bob showed me what WAS going on with my son. It was so simple, so logical and a game changer. Having witnessed first-hand what this drug free therapy does, I vowed I would some day come back and document this incredible story. I believe there could be millions of mis-diagnosed, ''labelled'' kids around the world; I hope this documentary goes some way in changing that.', 2018, NULL, 32, NULL, 'tt8300406', NULL, NULL, NULL, NULL);
