INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7373, 'tm537366', 'Nazareth', 2, 'After reaching the final rung on an empty corporate ladder, Nathan Tyler, a successful financier, shuns the bright city lights in favor of returning his disjointed family to his hometown of Nazareth in the mountains of NC. How hard could this all be? Turns out. Pretty Hard. Invited to be Provost of the local college, Nathan doesn''t find the chill rural life he remembers. Instead he must navigate the waters of ex-girlfriends, off-the-wall professors, and the sweet ineptness of small-town life.', 2017, 2, 26, NULL, 'tt5143192', NULL, NULL, NULL, NULL);
