INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7396, 'tm436407', 'Valentine DayZ', 2, 'Middle-aged Max and Sara meet and fall for each other in Palm Springs, but their love story is cut short due to a sudden zombie outbreak. Max is not as mild-mannered as he appears, and has a history involving government-sanctioned hits, but one zombie he isn''t able to kill is his darling Sara.', 2018, NULL, 79, NULL, 'tt5950092', 2.2, 147.0, 0.699, 6.5);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7397, 'tm318163', 'Holy Air', 2, 'Adam is a Christian Arab living in Nazareth - member of a vanishing minority within a minority in the Holy Land and the Middle East. His wife Lamia is a strong, beautiful and progressive Arab woman, who runs a foundation for women''s rights.', 2017, NULL, 81, NULL, 'tt6791482', 6.5, 168.0, 0.827, 5.8);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7398, 'tm974429', 'Hit a Lick', 2, 'A middle-aged ex-con hired to manage his nephew''s fledgling music career is caught between working for and taking down the neighborhood''s crime boss.', 2017, NULL, 92, NULL, 'tt1954512', 7.6, 18.0, 0.6, NULL);
