INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7400, 'ts111637', 'The Whole Package', 1, 'The search for the ultimate male underwear model. Models compete for a contract with apparel brand Dirt Squirrel, a photo spread in DNA Magazine and a cash tip. Each week they will be tested in challenges and photo shoots.', 2018, NULL, 26, 1.0, 'tt8240078', 6.6, 16.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7401, 'ts104491', 'Pinkfong! Car Songs', 1, 'Sing along to fun children''s songs and learn the names of various vehicles. Meet Pinkfong''s fun, educational videos that captured the hearts of millions of children around the world. Enjoy hundreds of kids'' favorite songs and stories created by Pinkfong, the official creator of global hit Baby Shark behind #BabySharkChallenge.', 2017, NULL, 1, 1.0, 'tt9310710', NULL, NULL, NULL, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7402, 'tm523041', 'ISIS: Enemies of Humanity', 2, '"A must watch film to know about the life of terrorists,their ideology and a solution which challenges this violent ideology".', 2017, NULL, 135, NULL, 'tt6755888', 6.5, 25.0, 1.4, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7403, 'tm679969', 'Frank & Fearless', 2, 'The killing of Reini''s mother by poachers sets these four on an ill-advised, sometimes funny, and deeply moving journey through the wild African bush to an equally-wild African city. Their purpose: to kidnap the ambassador of a South-East Asian country to force an end to the trade in rhino-horn and the slaughter of these wonderful animals.', 2018, NULL, 97, NULL, 'tt10112464', 5.1, 34.0, NULL, NULL);
