INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7614, 'tm470826', 'Gordon Lightfoot: If You Could Read My Mind', 2, 'From the song he refuses to perform to his admiration for Drake, a songwriting legend reflects on his lyrics and longevity with candour and humour. At 80 years young (and currently recording another album), Gordon Lightfoot continues to entertain and enlighten. Personal archive materials and studio sessions paint an intimate picture of an artist in his element, candidly revisiting his idealistic years in Yorkville''s coffeehouses, up through stadium tours and the hedonistic ''70s.', 2019, NULL, 88, NULL, 'tt10237902', 7.7, 443.0, 4.973, 6.6);
