INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7629, 'tm1084542', 'Murder in the Cove', 2, 'A cluster of postcard-perfect Acadian fishing villages off the coast of Nova Scotia, Canada made international news in 2013 when Phillip Boudreau, a local man known for poaching lobsters, was killed by fishermen in a crime the media dubbed ''Murder for Lobster.'' But as anyone from the community will tell you, it''s a lot more complicated than that. People don''t just go around killing each other over lobster.', 2020, 4, 52, NULL, 'tt15097206', 5.8, 32.0, 0.957, 4.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7630, 'tm1042006', 'Wander', 2, 'After getting hired to probe a suspicious death in the small town of Wander, a mentally unstable private investigator becomes convinced the case is linked to the same ''conspiracy cover up'' that caused the death of his daughter.', 2020, 5, 94, NULL, 'tt9689820', 4.9, 8777.0, 12.452, 5.4);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7631, 'ts249921', 'Jim Gaffigan: The Pale Tourist', 1, 'In The Pale Tourist, Gaffigan boldly goes where no stand-up comedian has gone before: everywhere. The two hour-long specials were filmed as part of Gaffigan''s The Pale Tourist worldwide tour, in which he traveled the world--in each country meeting people, eating the food, and learning a bit about the history. He would then transform those experiences into a stand-up set of all-new material and perform it for locals and expatriates, before heading on to another destination and doing it all over again.', 2020, NULL, 48, 1.0, NULL, NULL, NULL, 2.067, 6.2);
