INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7739, 'tm481561', 'Enemy Within', 2, 'When a Japanese pilot crash-lands on the tiny remote Hawaiian island of Ni''ihau, he is met with courtesy and traditional Hawaiian hospitality from the locals - until they discover he was part of the recent attack on Pearl Harbor.', 2019, NULL, 109, NULL, 'tt4837396', 4.6, 2013.0, 2.369, 4.0);
