INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7763, 'tm460600', 'Bolden', 2, 'A mythical account of the life of Buddy Bolden, the first Cornet King of New Orleans.', 2019, 5, 108, NULL, 'tt0858419', 5.4, 537.0, 3.842, 4.1);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7764, 'ts186880', 'Daughter of Lupin', 1, 'Despite coming from a long line of career criminals, Hana pursues a quiet life as a librarian. Until she falls in love with a cop on a mission to bring the family down.', 2019, NULL, 47, 2.0, 'tt10315062', 6.5, 70.0, 9.451, 8.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7765, 'tm961646', 'Finding Jesus', 2, 'When his daughter is kidnapped in the English channel waters, a single fish in the pacific must make the journey and track down his kidnapped daughter before it is too late', 2020, 3, 69, NULL, 'tt12981810', 1.1, 422.0, 1.588, 1.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7766, 'ts252101', 'World’s Toughest Race: Eco-Challenge Fiji', 1, 'From the creator of Survivor, 66 teams descend upon Fiji to compete in the most epic global adventure race ever attempted. Bear Grylls hosts this 11-day expedition that pushes competitors to their physical and emotional limits. For the veteran teams the goal is to win – but for most, the dream is to finish and prove to themselves and the world, that they can prevail in the World’s Toughest Race.', 2020, NULL, 47, 1.0, NULL, NULL, NULL, 1.352, 9.0);
