INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7772, 'tm946326', 'Reunion', 2, 'A pregnant woman returns to her recently-deceased grandparents’ old family home to spend time with her estranged mother. What begins as a tenuous reunion slowly turns terrifying.', 2020, NULL, 95, NULL, 'tt9741526', 4.4, 565.0, 2.982, 5.4);
