INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7804, 'tm888910', 'Dan Cummins: Get Outta Here; Devil!', 2, 'In his third hour special, comic and podcaster Dan Cummins presents some of his most outrageous material to date. Dan mocks those who believe in the lizard illuminati, a flat earth, the notion that you can sell your soul to Satan, and more. Dan even makes fun of himself for once having sex with a banana peel in a grocery store bathroom - nothing''s too weird or dark. Dan jokes about his kids, his ongoing hatred of strangers, and even offers to improve the world by killing a lot of people. Enjoy!', 2020, NULL, 71, NULL, 'tt11177282', 7.6, 117.0, 1.325, 8.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7805, 'tm444578', 'Bigil', 2, 'A do-gooder don wants his footballer son to uplift the life of his people by becoming a champion, but fate draws the youngster into a life of violence. Will he be able to fulfill his father’s dream when an opportunity comes his way seven years later?', 2019, NULL, 177, NULL, 'tt9260636', 7.2, 19381.0, 5.221, 6.6);
