INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7807, 'tm414351', 'Hesburgh', 2, 'He counseled presidents and popes, served on corporate boards and infuriated Richard Nixon.  He was one of the only friends to whom Ann Landers turned for advice.  During his 35 years as president of the University of Notre Dame, Theodore Hesburgh became one of the most influential and inspiring people of the 20th century.', 2019, NULL, 104, NULL, 'tt8403168', 7.8, 113.0, 2.415, 7.3);
