INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7835, 'tm469433', 'Pacto de Fuga', 2, 'During the last years of Pinochet''s military regime,  a group of militants from the "Manuel Rodríguez Patriotic Front" plan a prison break of political prisoners, through a tunnel that will take them 18 months to dig.', 2020, 2, 138, NULL, 'tt5538670', 7.0, 2022.0, 26.107, 7.7);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (7836, 'tm464240', 'Notebook', 2, 'An ex-army officer, Kabir, becomes a teacher in Kashmir in a school that is in a miserable condition. Things take a turn when Kabir finds a notebook, left behind by the previous year''s teacher Firdaus.', 2019, NULL, 115, NULL, 'tt9105014', 6.9, 2661.0, 2.718, 5.7);
