INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8019, 'tm945432', 'Among Us', 2, 'Based on the jaw-dropping contact accounts of individuals from around the world, AMONG US explores the suspicious phenomenon of non-human presence on Earth, from angels to ETs, and unveils the many ways they may be interacting, communicating and transferring subliminal information into our consciousness and potentially our DNA. The film ultimately shows that the interconnectedness of all species may be beneficial and most likely inevitable for the evolution of an intelligent universe. This film has been released in some territories under the title: "ET Contact: They are here".', 2019, NULL, 96, NULL, 'tt10891886', 5.5, 123.0, 3.944, 7.2);
