INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8022, 'tm891196', 'Deep Sea Monster Raiga vs. Lava Beast Ohga', 2, 'The giant monster Raiga returns, rising in Atami Harbor and attacking the city. A second kaiju, Ohga, soon joins the chaos, and the two monsters clash, destroying large sections of the city. Defense forces launch two new weapons, the giant tank Kamikaze and the drill tank Gokumei, to meet the the monster invasion head on. But as the beasts work their way to Tokyo, will they be enough to stop the monsters from laying waste to the city?', 2020, NULL, 83, NULL, 'tt13869368', 4.1, 35.0, 0.6, 6.0);
