INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8076, 'ts255728', 'Carolina Marín: Puedo porque pienso que puedo', 1, 'An inspiring look at the life of talented Spanish badminton player Carolina Marín.', 2020, NULL, 33, 1.0, 'tt12869152', 7.8, 78.0, 0.657, 10.0);
