INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8186, 'tm460176', 'Tone Bell - Can''t Cancel This', 2, 'Comedian Tone Bell simply wants to live in a world where Alaska is cold, student loans are paid and jelly is free. He''s finally found the one place his uncompromising view of this unfair world can''t be stopped.', 2019, NULL, 72, NULL, 'tt8358498', 7.5, 92.0, 1.991, 7.0);
