INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8230, 'tm494703', 'Vanilla', 2, 'A freewheeling comedian determined to save her family business invites an uptight entrepreneur on a road trip to sell a van with a complicated history. Romance ignites on their three day trip south, but is tested as they discover each other''s secrets. When the van sale deteriorates, they must decide if their very new connection is worth more than a very old van.', 2019, NULL, 87, NULL, 'tt8998752', 5.3, 134.0, 1.353, 6.0);
