INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8232, 'tm857237', 'South', 2, 'What kind of power is accessible through the discovery of a voice? Morgan Quaintance interlinks two anti-racist and anti-authoritarian liberation movements in South London and Chicago’s South Side with his own biography to explore what happens when speech is ignored, and the voice fades.', 2020, NULL, 28, NULL, NULL, NULL, NULL, 1.259, 6.3);
