INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8337, 'tm514370', 'Diamond in the Rough', 2, 'Michelle, a young teen in Colorado, loses her faith amidst extreme hardships and brief homelessness. With a mother battling drug and alcohol addiction since she was little, and war veteran father battling extreme PTSD, violence and dysfunction are the norm. But with a grandmother strong in her faith, and new friendships at school that break down walls, Michelle begins to realize that sometimes hardships often prepare ordinary people for an extraordinary destiny.', 2019, NULL, 95, NULL, 'tt7297994', 6.4, 28.0, NULL, NULL);
