INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8380, 'tm448703', 'Unda', 2, 'SI Manikandan and his police team are dispatched to Basthar, a Maoist area for election duty where they aren''t trained to handle the attacks in a territory field filled with land mines while being armed with unnecessary ammunition.', 2019, NULL, 130, NULL, 'tt7581552', 8.0, 4027.0, 2.608, 7.2);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8381, 'tm904195', 'Electrician', 2, 'Lonely electrician Mark wants to re-connect with his lost family unit, but he knows to achieve this it means re-opening doors to his past he has tried hard to get away from. The key to achieving his goal could also be his undoing and he must decide fast if he is willing to take that risk.', 2020, NULL, 85, NULL, 'tt12264546', 7.3, 95.0, 0.6, NULL);
