INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8386, 'ts228563', 'Yes & Yoga', 1, 'MPN Global original series, Yes and Yoga, is a mindfulness talk show that combines the improvisational comedy technique "Yes, And" with ancient Kundalini yoga techniques and meditation. Each episode features thought leaders from all areas of health, nutrition, and holistic medicine to give the viewer achievable goals to develop their own daily practice that includes yoga, meditation, and mindfulness thought techniques.', 2019, NULL, 22, 2.0, 'tt11098774', NULL, NULL, NULL, NULL);
