INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8390, 'tm833072', 'Chanakya', 2, 'Arjun aka Ramakrishna is a RAW marshall from Delhi who has a 100% success rate at nabbing terrorists. What happens when he makes enemies out of India''s most wanted Ibrahim Qureshi and his son Sohail?', 2019, NULL, 147, NULL, 'tt10944714', 5.5, 610.0, 1.574, 7.2);
