INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8404, 'ts90873', 'Haunted State', 1, 'This multi-part docuseries filmed over one year follows a team of filmmakers as they uncover historic elements behind various locations and investigate their paranormal idiosyncrasies.', 2019, NULL, 36, 1.0, 'tt9621922', 6.2, 113.0, 0.6, 10.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8405, 'tm827495', 'Bastaard', 2, 'Seventeen-year-old Daan does not have an easy time. His older brother Robbie died in an accident two years ago, which still leaves traces within the family. His mother Nina is locked up at home, his father Filip runs away from work. When mother and son meet the homeless Radja, Nina smells an opportunity to fill the void in her life again. Without consultation she brings Radja into the house. Relations within the family soon wither and sex and violence infect civil security. When Daan notices that the newcomer is gaining more and more power over his mother, he bites into his mysterious past. Soon he begins to fear that the intruder carries all the characteristics of a psychopath.', 2019, NULL, 104, NULL, 'tt7524624', 6.0, 262.0, 4.638, 5.8);
