INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8409, 'tm943442', 'No Love Lost', 2, 'After finalizing their divorce Noah and Moriah find themselves going from lovers to roommates. Moriah has moved on already and began dating her co-worker Anthony, 6 months before the divorce was final. Noah is still in love with her but find himself falling for a waitress named Rochelle.', 2019, NULL, 123, NULL, NULL, NULL, NULL, 2.072, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8410, 'tm899557', 'Anonymous Vol. 1 - The Dreamland Adventures the Mysteries of Atlantis', 2, '1.0 - An agent in NASA receives a packet by a new nation created from Hitler''s escape; has armed a doomsday device. Agent Schwartz turns to his Russian family as he tries to diffuse the weapon of mass destruction.', 2020, NULL, 178, NULL, 'tt12059646', 7.8, 5.0, NULL, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8411, 'tm1108690', 'Play', 2, 'For 17-year-old Jennifer, gaming has always been part of everyday teenage life. Recently she has been feeling uncomfortable and lonely. Not so long ago she moved to Munich with her parents Frank and Ariane from another city. In her new home, the girl does not find a real connection with her new classmates. Fixed by the virtual reality game "Avalonia", gaming is gradually becoming the elixir of life. Jennifer neglects her school and family responsibilities. She ignores all admonitions, restrictions and prohibitions for every precious second of the game and betrays her parents. Only the secret, excessive immersion in the virtual fantasy world of "Avalonia" seems to make Jennifer happy. The Parents have to watch as their daughter''s life gets completely out of balance between the real and the virtual world.', 2019, NULL, 89, NULL, 'tt8490100', 5.8, 192.0, 1.658, 4.8);
