INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8433, 'tm987538', 'Erica Rhodes: I Love You More', 2, 'Erica Rhodes is a regular panelist on Comedy Central’s @midnight and Fox’s Punchline. She has made appearances on SeeSo’s The Guest List, Hulu’s Coming to the Stage, AXS’ Live at Gotham and the syndicated Comics Unleashed. Erica has performed at San Francisco Sketchfest, the Moontower Comedy Festival (Austin, TX), the Blue Whale Comedy Festival (Tulsa, OK), the Boston Comedy Festival and RIOT LA Fest. Recent TV credits include ABC’s Modern Family, HBO’s Veep, Fox’s New Girl, and IFC’s Comedy Bang Bang. Erica stars in Audible’s Dr. Katz: The Audio Files and ABC Digital’s The Off Season. She recurs on TruTV’s Fameless and has been a semi-regular performer/writer on NPR’s A Prairie Home Companion.', 2019, NULL, 40, NULL, NULL, NULL, NULL, 0.6, NULL);
