INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8440, 'tm839501', 'Ardab Mutiyaran', 2, 'Babbu Bains, a finance recovery agent, doesn''t let anyone tell her what to do. She is independent and knows how to get things done her way, but then she gets married. Part of a new family now, can Babbu take a stand for herself?', 2019, NULL, 138, NULL, 'tt11122316', 7.3, 575.0, 1.412, 8.5);
