INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8513, 'tm855583', 'Choricha Mamla', 2, 'Thief breaks in politician''s house and politician''s affairs are revealed. Based on play by Italian author Dario Fo called Non tutti i ladri vengono a nuocere, translated to Marathi-saglec chor kahi lutayla yet nahi-kelyane bhashantar', 2020, NULL, 134, NULL, 'tt11457262', 6.5, 250.0, 0.656, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8514, 'tm898785', 'Urartu. The Forgotten Kingdom', 2, 'In the Bible, Urartu was the most ancient state on Earth. It was there where Noah’s ark stopped, and there where humanity found its salvation. The locals had a developed culture, economy, astronomy, and religious life. According to scientists’ latest discoveries, the culture of Urartu was the most advanced in the ancient world. And it had a great impact on the Persian Empire of the Achaemenids and ancient Greece. Due to a lack of research, Urartu is probably one of the most mysterious states in history. This documentary will introduce us to its unique background.', 2020, NULL, 50, NULL, 'tt13552578', 6.5, 53.0, 1.377, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8515, 'tm948791', 'Time Sleeper', 2, 'Sarah, upon accidentally discovering time travel through the use of a drug, must now travel back one year into the past to save her son from a fatal accident.', 2020, NULL, 93, NULL, 'tt9722688', 4.1, 52.0, 2.915, NULL);
