INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8518, 'tm1148716', 'Jeff Allen: Honor Thy Wife', 2, 'His Dry Bar Comedy videos have amassed millions of views on social media and other platforms, introducing him to tens of millions of new fans worldwide. Jeff Allen’s rapid-fire humor, which centers on marriage and family, is a hit with all ages.', 2020, NULL, 31, NULL, NULL, NULL, NULL, 0.6, NULL);
