INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8530, 'tm816689', 'Khandaani Shafakhana', 2, 'When Baby Bedi is entrusted with a job of running controversial sex clinic ‘Khandaani Shafakhana’, in a small town of Punjab, she faces severe backlash from all quarters. Can she find a cure for the widespread social stigma against important issues like sex education and sexual health?', 2019, NULL, 136, NULL, 'tt10519182', 4.3, 1905.0, 1.593, 6.2);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8531, 'tm1020516', 'House of Quarantine', 2, 'Nine people have been locked down together in a house while trying to make a movie. Unknowingly, one of their group is infected with Covid-19. The next three weeks become a life and death struggle for survival with no help from the outside amidst a global pandemic and national chaos.', 2020, NULL, 81, NULL, 'tt12440242', 6.6, 766.0, 1.527, NULL);
