INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8634, 'tm972028', 'Writing Kim', 2, 'Annie is an ambitious young writer who visits her affluent, married, friend, Kim at the home she shares with her husband and young son. As Annie works on her writing in this informal retreat, she becomes increasingly inspired and intrigued by Kim’s charismatic charm and seemingly fluid sexuality.', 2020, NULL, 78, NULL, 'tt4870420', 6.4, 22.0, 1.253, 1.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8635, 'tm978135', 'Aravind SA - I Was Not Ready Da', 2, 'Imagine two flowers pollinating on screen for 75 minutes - welcome to Aravind SA''s "I Was Not Ready Da". This is that show that the whole family should watch - just not together. From his teenage love for white people and chatroom, to his all inclusive approach to strip clubs in America, SA walks us through many such contradictions of traumatising Sanskrit tutors, to provoking news anchors in their own shows. Get ready to meet SA, the man who is finally ready to tell you about the times life threw shit, and he hilariously took the hit.', 2020, NULL, 75, NULL, NULL, NULL, NULL, 1.195, 8.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8636, 'tm860740', 'Girlz', 2, 'Mati, an 18-year-old college girl convinces her conservative parents to let her go on an independent trip to Goa where she meets two other women who come from different backgrounds.', 2019, NULL, 153, NULL, NULL, NULL, NULL, 1.187, NULL);
