INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8645, 'tm872645', 'United States of Tents', 2, 'An estimated 500,000 U.S. citizens, veterans and children are homeless across the nation. A newly-released documentary by filmmaker Dennis Michael Lynch tackles the homeless crisis in America head-on. "United States of Tents," takes viewers on a journey to several homeless camps across the country, and includes interviews with leaders in many communities who are addressing this devastating crisis.', 2019, NULL, 91, NULL, 'tt11426160', 6.9, 91.0, 1.897, 7.0);
