INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8651, 'tm469334', 'Jill-Michele Meleán: White / Latina', 2, 'Jill-Michele Melean has finally filmed her one-hour standup special. From Miami to L.A. She''s half Bolivian, half Irish but raised in Miami so Cuban by association. Not white enough to play the Stepford wife or Latin enough to play the gangsta but relatable to all ethnicities. From impressions, to family to dating, this special has her last 15 years of hilarious stories.', 2019, NULL, 62, NULL, 'tt11682998', 5.5, 17.0, 0.605, NULL);
