INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8662, 'tm473308', 'Height of the Wave', 2, 'Yeon-su, the police officer, is dispatched to an island and starts to witness strange situations. Yae-un, who lives in the island after she lost her parents when she was young, and the others´ behavior terrifies Yeon-su. Film director Park who constantly focused on stories related to human greed and collapse, deeply explores the guilt of human and the possibility of redemption again.', 2019, NULL, 95, NULL, NULL, NULL, NULL, 2.304, 6.2);
