INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8668, 'tm876073', 'ReWilding Kernwood', 2, 'For three decades, Jean Aspen and Tom Irons called Alaska''s remote Brooks Range home. Choosing to live lightly with the land, their family built a log cabin and explored the valley on foot-a journey they shared in books and documentaries. Now elders, the couple decide to close the circle and erase their footprints. In their third documentary, they dismantle their home and carefully restore the site to intact wilderness while exploring stewardship, responsibility, and human belonging to our living Earth. ReWilding Kernwood is a layered conversation on release, completion, and finding purpose in the shifting mystery of life.', 2020, NULL, 86, NULL, 'tt11656686', 8.4, 21.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8669, 'tm679061', 'Adoring', 2, 'Star-studded holiday ensemble comedy about pets and their owners lives.', 2019, 2, 108, NULL, 'tt10203982', 5.5, 175.0, 4.052, 7.3);
