INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8677, 'tm856120', 'Letters of Hope', 2, 'Set in 1976 Apartheid-era South Africa and based on a true story, this powerful film tells the story of a young man caught between his father''s wishes and his own dreams. After his father is brutally killed, 16-year-old Jeremiah discovers that he had been delivering secret letters from freedom fighters in exile and prison on his rounds as a postman. When he learns that his father''s last wish was for him to take over this work and continue delivering the letters, Jeremiah — who dreams of joining the police force — faces an impossible choice.', 2020, NULL, 75, NULL, 'tt18765190', NULL, NULL, 0.863, NULL);
