INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8681, 'tm820048', 'Defend, Conserve, Protect', 2, 'Narrated by Dan Aykroyd, Defend, Conserve, Protect, pits the marine conservation group, Sea Shepherd, against the Japanese whaling fleet, in an epic battle to defend the majestic Minke whales.', 2019, NULL, 74, NULL, 'tt4718276', 8.8, 19.0, 0.916, NULL);
