INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8684, 'tm492382', 'Manipulated', 2, 'Manipulated is a taut drama/mystery/whodunnit with an ensemble cast. District Attorney Diane Conrad is under extreme pressure to resolve a case that has politicians and the local community on edge. The clock is ticking and the stakes and emotions are running high. Can anyone trust what they see or hear? Why is Detective Scott Keating taking the biggest gamble of his career? With evidence in short supply, and the personal and professional lives of all concerned unraveling, can you believe anything anyone says? Game on.', 2019, NULL, 92, NULL, 'tt10515934', 3.8, 149.0, 0.689, 6.5);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8685, 'tm954312', 'A New Husband for Christmas', 2, 'Centered around one couple (Stan and Kelly Stevenson) who seem to be more committed to growing apart rather than growing together. Their friends are caught in the middle of divorce conversations during one of the most joyous seasons of the year. Rather working things out, Kelly''s one wish for Christmas is for Jesus to bless her with a new husband.', 2020, NULL, 103, NULL, NULL, NULL, NULL, 3.76, 8.0);
