INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8688, 'tm512452', 'D-Day at Pointe-du-Hoc', 2, 'The incredible story of the U.S. Army Rangers who assaulted the 100 foot-high cliffs of Pointe-du-Hoc on June 6, 1944, where 6 German cannons were supposed to be located and taken out. Narrated by David McCallum and Donnie Wahlberg Documentary to include: -Interviews with D-Day and Pointe-du-Hoc survivors. -Exclusive Drone footage of the cliffs at Pointe du Hoc. -Exclusive Drone footage of the English Channel approach to Pointe du Hoc and of the seaward side of the cliffs themselves.', 2019, NULL, 55, NULL, 'tt7524720', 8.2, 109.0, 0.6, 8.5);
