INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8693, 'tm815842', 'The Road to Cabazon', 2, 'Sam just lost custody of his daughter, Emma. As a last-ditch-effort to connect with Emma, Sam decides to drive her across country to her mother on the west coast. Things get complicated when Sam is unable to drive and his ex-brother-in-law, Dave, must do the job.', 2020, NULL, 97, NULL, 'tt10477300', 7.9, 9.0, NULL, NULL);
