INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8848, 'tm904596', 'Baggy in & as KungFu Bonda: A Mostly English Stand Up Comedy Special', 2, 'Baggy takes you on a hilarious journey about growing older, the changes it brings and coming to terms with it. His observations on adulting, parents, marriage, sex and grill gates will leave you in splits, while his anecdotal stories will keep you gripped through the show. Guaranteed to leave you laughing, content and hopefully a little more at peace with your own life''s developments.', 2020, NULL, 77, NULL, 'tt12199368', 4.9, 22.0, 0.6, 7.0);
