INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8857, 'ts230062', 'AWS DeepRacer TV', 1, 'AWS DeepRacer TV takes viewers inside the AWS DeepRacer League, the world''s first global autonomous racing league featuring 1/18th scale race cars powered by reinforcement learning. Each episode travels to a new city, capturing a frantic buildup to live racing, introducing compelling new competitors, and awarding one winner the chance to take on the world''s fastest at the Championship Cup during AWS re:Invent 2019. Every installment of DeepRacer TV features real drama, authentic characters to root for, big stakes, relatable stories, and a race against the clock. Watch as developers of every background and skill level train their models, employ unique strategies, and discover the potential of reinforcement learning in a fun and competitive environment. Developers, start your engines.', 2019, NULL, 17, 1.0, 'tt11247190', NULL, NULL, NULL, NULL);
