INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8890, 'tm920846', 'Incident at Guilt Ridge', 2, 'Dev and Jonas are two rogues on sort-of-opposite sides of the law in the 1880''s. When they accept a job that seems like easy money from a powerful mining company owner, they end up getting more than they bargained for.', 2020, NULL, 76, NULL, 'tt9464000', 3.4, 86.0, 1.4, 2.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8891, 'ts101922', 'The Ride That Got Away', 1, 'For every true car love there''s the ride that got away. That special car they were forced to give up that will always hold a sacred place in their heart. Whether to pay medical bills, buy a house, or cover the cost of a college education, they''ve always dreamed of some day getting it back.', 2019, NULL, 43, 1.0, 'tt9647180', 7.5, 22.0, NULL, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8892, 'ts214494', 'Jestination Unknown', 1, 'Jestination Unknown is an attempt to answer the question, what does India find funny? The clubs and pubs of India''s metros are only a sliver of an answer to that question. English stand-up comedy maybe new in India but comedy itself isn''t new to the country. The people of this country have laughed at kings, foreigners, neighbors, relatives, and more importantly, themselves. In a time when jokes are considered offensive, what if India answered otherwise?', 2019, NULL, 36, 1.0, 'tt10350924', 5.8, 256.0, 1.346, 8.0);
