INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8914, 'tm452832', 'Azeem Banatwalla: Problems', 2, 'Azeem Banatwalla''s second stand-up special is a wickedly dark show that taps into the inner, evil voice in the back of all our heads, and uses it to solve the biggest problems plaguing the country – stupidity, moral policing, racism, indoctrination, overpopulation, Kashmir, the government, and of course, Pigeons. There’s also a joke about Salman if that’s what you’re into. Nobody’s judging you', 2019, NULL, 67, NULL, 'tt9569212', 7.8, 296.0, 1.005, 6.8);
