INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8923, 'tm927961', 'Touch', 2, 'Fei Fei, a married Caucasian western woman meets Bai Yu, a Chinese blind masseur. When they come together in an intense love affair they find the demons they''ve created implode in a clash of violent impulses.', 2020, NULL, 97, NULL, 'tt12483492', 5.2, 65.0, 0.671, 5.0);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8924, 'tm569360', 'Counter Histories: Rock Hill', 2, 'Meet the men who stood up for their rights by sitting down at the counter of the Rock Hill, SC Five and Dime. They asked for a cup of coffee and were instead met with violence, police brutality and unjust imprisonment. A small town miles from Charlotte, NC, Rock Hill became a landmark of the Civil Rights Movement, one that too few remember today. Students of Friendship College took on the weight of discrimination under the banner of non-violence and ''Jail No Bail.'' The tactic spread across the South, inspiring protesters to no longer fund their own oppression through bonds and fines. The courage of these men ignited a passion and furor that rose into the famed Freedom Rides.', 2019, NULL, 53, NULL, 'tt4364196', 7.2, 11.0, 0.6, NULL);
INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (8925, 'ts220801', 'Serbia Old and New', 1, 'Join Laura Alexandra as she travels Serbia for the first time in this 6 part series. Serbia has connected West with East for centuries - a land in which civilisations, cultures, faiths, climates and landscapes meet and mingle - and Laura experiences just some of these offerings in this travel series.', 2019, NULL, 46, 1.0, 'tt10870338', NULL, NULL, NULL, NULL);
