INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (9421, 'tm999616', 'Bastille ReOrchestrated', 2, 'A bracingly honest new documentary sourced from hundreds of hours of unseen archive and all-new conversations captured during the pandemic, the film features open and frank insights from each band member plus collaborators inextricably linked to the group’s orchestral adventures. Alongside dramatic re-interpretations of their hit songs, ReOrchestrated charts the very beginning of the band’s foundations all the way through the highs and lows of their three albums to date, via landmark, full orchestra appearances at Royal Albert Hall, Elbphilharmonie in Hamburg and The London Palladium, not to mention the inevitable tensions encountered en route.', 2021, NULL, 70, NULL, 'tt14030006', 8.2, 101.0, 2.707, 9.5);
