INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (9514, 'tm1016257', 'Truly Texas Mexican', 2, 'Over time and during conquest, "comida casera," home cooking of Texas Mexican families sustained indigenous identity and memory. Cooking deer, cactus and tortillas, women led the cultural resistance against colonization. This road movie weaves through Texas cities, names the racism that erased Native American history. It celebrates a new type of encounter, one with a table where All are welcome.', 2021, NULL, 86, NULL, 'tt13932972', 6.3, 51.0, 0.919, NULL);
