INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (9582, 'tm1056639', 'Pedja Bajovic: The Balkan Brian', 2, 'You thought you already knew enough about the Balkans; or simply never bothered to learn anything about it? You''re not to blame as the images you had encountered were mostly those of war atrocities, too many historical references, ongoing crime with much corruption and not so much teeth. Yes, there is also beautiful nature there, delicious cuisine and upbeat music - However, is there anything funny at all about it? Well, here''s a chance for you to find out. Delivered in a hour-long show by one of their natives, in a manner best described by its slogan: Filthy Mouth. Clean Heart. Balkan Brain.', 2021, NULL, 30, NULL, 'tt14468638', NULL, NULL, NULL, NULL);
