INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (9669, 'tm1010682', 'Boycie in Belgrade', 2, 'Join John Challis on his journey to the capital of Serbia, Belgrade, where he aims to uncover why ‘Only Fools and Horses’ is so popular in the small Balkan nation, apparently it’s the most watched show in Serbia, but why? Boycie is received in Serbia as almost a national hero, causing a media frenzy everywhere he goes on his voyage to learn about the people and the country. From a Royal Palace, to a brandy distillery, to a university teaching cockney rhyming slang; the documentary will keep you entertained as well as discover what it is that unites this tiny Balkan state with British humour.', 2021, NULL, 79, NULL, 'tt13670588', 7.1, 108.0, 1.551, 6.0);
