INSERT INTO [Show] (ID,JustWatchShowID,Title,ShowTypeID,Description,ReleaseYear,AgeCertificationID,Runtime,Seasons,ImdbID,ImdbScore,ImdbVotes,TmdbPopularity,TmdbScore) VALUES (9700, 'tm1043432', 'Gaurav Gupta: Market Down Hai', 2, '''Market Down Hai'', Gaurav Gupta''s one hour is a spot on culmination of years of observation and personal anecdotes on the Baniya Way of Life. Having experienced that since childhood, he draws his humour and relatablity from his own personal experiences which not only make it engaging but also allow us insights on hacks to survive the word of Business Conquering Baniyas, as he likes to call it. Gupta in his own effortless style and approach to call out and make the best of his own personal experiences, humours us all in this one hour, it''s everything but mundane.', 2021, NULL, 50, NULL, 'tt14624470', 7.4, 335.0, 0.6, 6.0);
